insert into public.items (skill_id, subskill_id, tier, b, kind, passage, stem, choices, answer, explanation, rationales) values
  ('rw.ii.central', 'rw.ii.central.main', 'easy', -1, 'mcq', 'Marisol Vega, a ceramicist in a small coastal town, fires her pottery in a wood-burning kiln that takes three days to cool. She could switch to an electric kiln and finish pieces in hours, but she says the slow cooling creates glaze patterns she cannot predict or reproduce. For Vega, that unpredictability is the point: each bowl records the particular conditions of its firing.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Vega values her wood-burning kiln because it produces glazes that cannot be repeated."},{"id":"B","text":"Electric kilns are more efficient than wood-burning kilns."},{"id":"C","text":"Vega plans to switch to an electric kiln to save time."},{"id":"D","text":"Most ceramicists in coastal towns use wood-burning kilns."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The text explains why Vega keeps a slow wood-burning kiln: its cooling produces unpredictable, one-of-a-kind glazes, which she sees as the point.', '{"B":"The text mentions that electric kilns are faster, but that is a supporting detail, not the main idea.","C":"The text says she could switch but chooses not to.","D":"The text says nothing about what most ceramicists do."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'easy', -1, 'mcq', 'In 1998, the town of Linden Falls converted an abandoned rail line into a walking path. City planners expected only modest use, but within five years the path averaged more than two thousand visitors a day. Shops along the route reopened, and the town later extended the path into two neighboring counties.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Planners in Linden Falls are usually wrong about public projects."},{"id":"B","text":"A path built on an old rail line was far more popular than expected and benefited the area."},{"id":"C","text":"The rail line was abandoned because shops along it had closed."},{"id":"D","text":"Neighboring counties built walking paths before Linden Falls did."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The text describes the path''s unexpected popularity and its effects: reopened shops and an extension into nearby counties.', '{"A":"One wrong estimate does not show planners are usually wrong; this overgeneralizes.","C":"The text never explains why the rail line was abandoned.","D":"The text says Linden Falls extended its path into those counties, not that they built paths first."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'medium', 0, 'mcq', 'Biologist Ren Okafor has recorded the songs of a population of sparrows on Kesh Island for six years. She noticed that a young bird''s song often resembles the songs of birds in neighboring territories more than the songs of its parents. Okafor hypothesizes that the sparrows learn new song variations mainly from neighbors rather than from their parents.', 'Which finding, if true, would most directly support Okafor''s hypothesis?', '[{"id":"A","text":"Sparrows on Kesh Island sing more often in spring than in autumn."},{"id":"B","text":"Young sparrows raised only with their parents sang their parents'' song variations."},{"id":"C","text":"Young sparrows raised apart from their parents but near unrelated adults sang the adults'' variations."},{"id":"D","text":"Kesh Island has more songbird species than the nearby mainland."}]'::jsonb, '{"choice":"C"}'::jsonb, 'If birds separated from their parents still pick up the songs of unrelated nearby adults, then neighbors, not parents, are the source of learning, which is exactly Okafor''s hypothesis.', '{"A":"When birds sing says nothing about whom they learn from.","B":"This shows birds can learn from parents, which does not support learning mainly from neighbors.","D":"The number of species is unrelated to how sparrows learn songs."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'medium', 0, 'mcq', 'Some historians argue that the spread of affordable bicycles in the late nineteenth century changed how young people in rural areas chose marriage partners. Before bicycles, the argument goes, most people married someone from their own village; afterward, they could easily travel to court someone in a nearby town.', 'Which finding, if true, would most strongly support the historians'' argument?', '[{"id":"A","text":"Bicycles cost more in cities than in rural areas at the time."},{"id":"B","text":"The average distance between spouses'' birthplaces stayed the same throughout the period."},{"id":"C","text":"Many young people used bicycles mainly for racing."},{"id":"D","text":"Marriage records show the average distance between spouses'' birthplaces rose sharply after bicycles became affordable."}]'::jsonb, '{"choice":"D"}'::jsonb, 'The argument predicts that people began marrying partners from farther away once bicycles were common. Rising distances between spouses'' birthplaces after that point would directly support it.', '{"A":"Price differences between cities and rural areas do not address whom people married.","B":"Unchanged distances would weaken the argument, not support it.","C":"How bicycles were mainly used does not show any change in marriage patterns."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'hard', 1, 'mcq', 'Engineers testing a new road surface found that it reduced tire noise by 40 percent compared with standard asphalt. However, the new surface also wore down twice as fast while costing about the same to install. A city that has received many complaints about traffic noise from residents along one highway, and that can afford more frequent repaving there, would therefore most likely ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"find the new surface useful along that highway, while expecting to replace it more often."},{"id":"B","text":"avoid the new surface because it costs more to install than standard asphalt."},{"id":"C","text":"choose the new surface because it lasts longer than standard asphalt."},{"id":"D","text":"conclude that tire noise is unrelated to the type of road surface."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The surface solves the city''s noise problem, and the city can afford the faster wear, so it would likely use the surface there and accept more frequent replacement.', '{"B":"The text says installation costs are about the same.","C":"The text says the new surface wears down faster, not slower.","D":"The test showed the surface does change tire noise."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'hard', 1, 'mcq', 'Archaeologists excavating an ancient settlement found grinding stones with traces of wild barley dated to about 11,000 years ago. The earliest domesticated barley in the region appears only in layers roughly 1,500 years younger. Because the grinding stones show heavy, repeated use, the researchers concluded that the settlement''s inhabitants ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"never ate barley of any kind."},{"id":"B","text":"domesticated barley before they began gathering wild barley."},{"id":"C","text":"regularly processed wild barley long before domesticated barley appeared there."},{"id":"D","text":"used the grinding stones only for decoration."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Heavily used stones with wild barley residue, about 1,500 years older than the first domesticated barley, indicate that people regularly processed wild barley well before cultivation.', '{"A":"Barley traces on heavily used grinding stones show that barley was processed.","B":"This reverses the order shown by the dated layers.","D":"Heavy, repeated use with food residue indicates practical use, not decoration."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'easy', -1, 'mcq', 'The committee''s report was so ______ that readers could find the answers to their questions in just a few minutes: every section was short, clearly labeled, and free of unnecessary detail.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"lengthy"},{"id":"B","text":"concise"},{"id":"C","text":"ornate"},{"id":"D","text":"secretive"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Short sections free of unnecessary detail describe a concise report.', '{"A":"A lengthy report contradicts \"every section was short.\"","C":"\"Ornate\" means elaborately decorated, the opposite of free of unnecessary detail.","D":"Nothing suggests the report hid information; readers found answers quickly."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'easy', -1, 'mcq', 'Although the hiking trail looked ______ on the map, its steep switchbacks and loose rocks made it one of the most demanding routes in the park, and many visitors turned back before reaching the top.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"treacherous"},{"id":"B","text":"crowded"},{"id":"C","text":"manageable"},{"id":"D","text":"unmarked"}]'::jsonb, '{"choice":"C"}'::jsonb, '"Although" sets up a contrast with how demanding the trail really was, so on the map it must have looked manageable.', '{"A":"\"Treacherous\" agrees with the trail''s real difficulty, so it does not create the contrast that \"Although\" requires.","B":"How crowded the trail looked does not contrast with its difficulty.","D":"The trail appears on the map, and \"unmarked\" does not contrast with being demanding."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.function', 'medium', 0, 'mcq', 'Most people assume that deserts are silent places. In fact, wind moving across certain sand dunes can produce a low hum that is audible from far away. Researchers have found that the sound occurs only when sand grains of a particular size slide down a dune''s face together, vibrating in unison.', 'Which choice best describes the function of the first sentence in the overall structure of the text?', '[{"id":"A","text":"It states a finding that the researchers later confirm."},{"id":"B","text":"It presents a common belief that the rest of the text complicates."},{"id":"C","text":"It gives an example that supports the text''s final claim."},{"id":"D","text":"It describes a method the researchers used."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The first sentence states what most people assume, and "In fact" introduces evidence that deserts can produce sound, complicating that belief.', '{"A":"The researchers'' work challenges the idea in the first sentence rather than confirming it.","C":"The first sentence is a belief, not an example, and it runs against the final claim.","D":"No research method is described in the first sentence."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.purpose', 'medium', 0, 'mcq', 'Translator Ilse Brandt kept a notebook of words that had no direct equivalent in English. Over twenty years, the notebook grew to more than four hundred entries. Rather than inventing new English words, Brandt usually described each term in a short phrase, believing that a careful explanation preserved more of the original meaning than a coined word could.', 'Which choice best states the main purpose of the text?', '[{"id":"A","text":"To argue that English needs more invented words"},{"id":"B","text":"To compare the size of different languages'' vocabularies"},{"id":"C","text":"To explain why Brandt stopped working as a translator"},{"id":"D","text":"To describe a translator''s practice and the reasoning behind it"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The text describes what Brandt did (kept a notebook and explained untranslatable words in phrases) and why (explanations preserve more meaning).', '{"A":"Brandt avoided inventing words; the text does not argue for them.","B":"No vocabularies are compared.","C":"The text never says Brandt stopped translating."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'hard', 1, 'mcq', 'Text 1
Many city planners favor adding lanes to crowded highways. More lanes, they argue, give cars room to spread out, so traffic should move faster and commutes should become shorter.

Text 2
Transportation researcher Dana Imre studied highways that were widened over the past thirty years. She found that within a few years the new lanes were as congested as the old ones had been, because faster commutes encouraged more people to drive.', 'Based on the texts, how would Imre (Text 2) most likely respond to the planners'' argument in Text 1?', '[{"id":"A","text":"She would agree that wider highways permanently shorten commutes."},{"id":"B","text":"She would argue that any improvement in commute times is likely to be temporary because widening attracts more drivers."},{"id":"C","text":"She would argue that cities should stop building highways of any kind."},{"id":"D","text":"She would claim that highways were less crowded thirty years ago because they had more lanes."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Imre found that added lanes filled up again within a few years as more people drove, so she would say the faster traffic planners predict does not last.', '{"A":"Her findings show the benefit does not last.","C":"Text 2 makes no recommendation about building highways in general.","D":"Text 2 does not compare highways thirty years ago by number of lanes."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'hard', 1, 'mcq', 'Text 1
Some nutrition writers claim that eating breakfast speeds up metabolism, so people who skip it are likely to gain weight.

Text 2
In a twelve-week study led by nutrition scientist Paolo Reyes, adults were randomly assigned either to eat breakfast or to skip it. Both groups ate about the same total number of calories each day, and their weight changes did not differ. Reyes cautions that the study was short and did not include children.', 'Based on the texts, how would Reyes (Text 2) most likely respond to the claim in Text 1?', '[{"id":"A","text":"He would say his findings prove the claim for all age groups."},{"id":"B","text":"He would say the claim is true only for adults."},{"id":"C","text":"He would say his findings do not support the claim, while noting limits on what his study can show."},{"id":"D","text":"He would say people should remove breakfast from their diets."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Reyes found no weight difference between adults who ate breakfast and those who skipped it, which contradicts the claim, but he notes the study was short and excluded children.', '{"A":"His study found no effect, and it excluded children.","B":"His results did not support the claim even for the adults he studied.","D":"Finding no difference does not mean breakfast should be removed."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'easy', -1, 'mcq', 'Hummingbirds have extremely fast metabolisms and must feed every few minutes during the day. ______ at night they can enter a sleeplike state called torpor, lowering their body temperature to save energy.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"For example,"},{"id":"B","text":"However,"},{"id":"C","text":"Similarly,"},{"id":"D","text":"As a result,"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Constant daytime feeding contrasts with slowing down at night, so a contrast transition fits.', '{"A":"Entering torpor at night is not an example of frequent daytime feeding.","C":"Torpor is the opposite of frequent feeding, not something similar to it.","D":"Frequent feeding does not cause torpor; the sentences contrast."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.cause', 'easy', -1, 'mcq', 'The museum''s new wing was designed to let in as much natural light as possible. ______ the architects installed tall windows along every outside wall and added skylights above the main gallery.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Nevertheless,"},{"id":"B","text":"In contrast,"},{"id":"C","text":"To that end,"},{"id":"D","text":"Still,"}]'::jsonb, '{"choice":"C"}'::jsonb, 'The windows and skylights are the means of achieving the stated goal, so "To that end" fits.', '{"A":"\"Nevertheless\" signals something done despite the first sentence, but the windows serve its goal.","B":"Nothing in the second sentence contrasts with the first.","D":"\"Still\" implies a concession, but there is no tension between the sentences."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.cause', 'medium', 0, 'mcq', 'Early telephone networks required an operator to connect every call by hand. As the number of subscribers grew, this system became slow and expensive to run. ______ engineers developed automatic switches that could connect calls without an operator.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Nonetheless,"},{"id":"B","text":"For instance,"},{"id":"C","text":"Likewise,"},{"id":"D","text":"Consequently,"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The slow, expensive manual system led to the development of automatic switches, a cause-and-effect relationship.', '{"A":"\"Nonetheless\" signals that something happened despite the problem, but the problem prompted the switches.","B":"Automatic switches are a response to the problem, not an example of it.","C":"The switches are not similar to the manual system; they replace it."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'medium', 0, 'mcq', 'Recycled plastic can be turned into durable building materials such as fence posts and park benches. ______ these products are difficult to recycle again, so critics argue that the process mainly delays the plastic''s arrival in a landfill.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"However,"},{"id":"B","text":"Therefore,"},{"id":"C","text":"In other words,"},{"id":"D","text":"For this reason,"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The first sentence presents a benefit and the second a drawback, so a contrast transition is needed.', '{"B":"Being durable does not cause the products to be hard to recycle.","C":"The second sentence adds a new point rather than restating the first.","D":"The benefit in the first sentence is not the reason for the drawback."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'hard', 1, 'mcq', 'While researching a topic, a student has taken the following notes:
• The Kestrel River Bridge opened in 1931.
• It is a suspension bridge with a main span of 420 meters.
• The Ardon Bridge opened in 1964.
• It is a cable-stayed bridge with a main span of 610 meters.', 'The student wants to emphasize a difference in length between the two bridges'' main spans. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"The Kestrel River Bridge opened in 1931, and the Ardon Bridge opened in 1964."},{"id":"B","text":"The Kestrel River Bridge is a suspension bridge, while the Ardon Bridge is cable-stayed."},{"id":"C","text":"The Ardon Bridge has a main span of 610 meters."},{"id":"D","text":"The Ardon Bridge''s main span (610 meters) is 190 meters longer than that of the Kestrel River Bridge (420 meters)."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Only this choice gives both span lengths and states the difference (610 − 420 = 190 meters).', '{"A":"This compares opening dates, not span lengths.","B":"This compares bridge types, not span lengths.","C":"This gives one length without any comparison."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'hard', 1, 'mcq', 'While researching a topic, a student has taken the following notes:
• Composer Lena Haas wrote her first symphony at age 19.
• The symphony premiered in Vienna in 1902.
• Critics praised its unusual use of the harp.
• Haas later wrote three operas.', 'The student wants to introduce Haas''s first symphony to an audience unfamiliar with Haas. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Critics praised the unusual use of the harp."},{"id":"B","text":"Lena Haas, a composer who later wrote three operas, completed her first symphony at age 19; it premiered in Vienna in 1902."},{"id":"C","text":"The symphony premiered in Vienna in 1902."},{"id":"D","text":"Haas wrote three operas after her symphony premiered."}]'::jsonb, '{"choice":"B"}'::jsonb, 'An unfamiliar audience needs to know who Haas is and what the symphony is. This choice identifies her as a composer and introduces the symphony with its key facts.', '{"A":"This does not say which work is meant or who Haas is.","C":"This does not identify Haas for an unfamiliar audience.","D":"This focuses on the operas rather than introducing the symphony."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.sentence', 'easy', -1, 'mcq', 'The project, organized by a local high school, aims to restore shade along the water. Last month the volunteers planted two hundred oak seedlings along the ______ next spring they will return to measure how many survived the winter.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"riverbank,"},{"id":"B","text":"riverbank"},{"id":"C","text":"riverbank, and,"},{"id":"D","text":"riverbank;"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Two independent clauses ("the volunteers planted…" and "next spring they will return…") can be joined with a semicolon.', '{"A":"A comma alone between two independent clauses creates a comma splice.","B":"With no punctuation, the two independent clauses run together.","C":"The comma after \"and\" is incorrect; it separates the conjunction from the clause it introduces."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.semicolon_colon', 'easy', -1, 'mcq', 'Glass frogs, found in the forests of Central and South America, get their name from their translucent ______ on some species, the heart and digestive organs are visible through the skin of the belly.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"undersides:"},{"id":"B","text":"undersides,"},{"id":"C","text":"undersides"},{"id":"D","text":"undersides, which"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The second clause explains what "translucent undersides" means, and a colon correctly introduces an independent clause that explains the first.', '{"B":"A comma alone between two independent clauses creates a comma splice.","C":"With no punctuation, the two independent clauses run together.","D":"\"Which\" makes the second part a relative clause that does not fit grammatically with \"on some species, the heart…\"."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.sv', 'medium', 0, 'mcq', 'After the expedition returned, its members donated their journals and maps to the city. The collection of letters written by the explorer''s crew members ______ now housed in the city''s maritime museum.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"are"},{"id":"B","text":"were"},{"id":"C","text":"is"},{"id":"D","text":"have been"}]'::jsonb, '{"choice":"C"}'::jsonb, 'The subject is the singular noun "collection," not "letters" or "members," so the singular verb "is" is required.', '{"A":"\"Are\" is plural; it agrees with \"members,\" which is not the subject.","B":"\"Were\" is plural and also shifts to the past tense, which conflicts with \"now.\"","D":"\"Have been\" is plural and does not agree with \"collection.\""}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.pronoun', 'medium', 0, 'mcq', 'This year''s regional science fair focused on clean water. Each of the student teams presented ______ design for a low-cost water filter to a panel of local engineers.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"it''s"},{"id":"B","text":"its"},{"id":"C","text":"they''re"},{"id":"D","text":"their"}]'::jsonb, '{"choice":"B"}'::jsonb, 'The antecedent is "Each," which is singular, so the singular possessive "its" is needed.', '{"A":"\"It''s\" means \"it is,\" not a possessive.","C":"\"They''re\" means \"they are,\" not a possessive.","D":"\"Their\" is plural and does not agree with the singular \"Each.\""}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.supplements', 'hard', 1, 'mcq', 'Painter Hiroshi Tanabe, who spent a decade studying the traditional mineral pigments of his region ______ grinds his own colors from stones he collects on long mountain hikes.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"region—"},{"id":"B","text":"region;"},{"id":"C","text":"region"},{"id":"D","text":"region,"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The clause "who spent a decade… region" interrupts the main sentence and opens with a comma, so it must close with a matching comma before the verb "grinds."', '{"A":"A dash cannot close an interruption that opened with a comma.","B":"A semicolon would separate the subject \"Tanabe\" from its verb \"grinds.\"","C":"Without a closing comma, the interruption runs into the main clause."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.modifier', 'hard', 1, 'mcq', 'The expedition had been planned for nearly three years, and its members had studied every route to the peak in detail. Having trained for months in high-altitude conditions, ______', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"the summit was reached by the team of climbers two days ahead of schedule."},{"id":"B","text":"two days ahead of schedule, the summit was reached by the climbers."},{"id":"C","text":"the team of climbers reached the summit two days ahead of schedule."},{"id":"D","text":"the schedule was beaten by two days by the team of climbers."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The modifier "Having trained for months…" must be followed directly by the people who trained: the team of climbers.', '{"A":"This makes \"the summit\" the thing that trained for months: a dangling modifier.","B":"This places \"two days ahead of schedule\" and then \"the summit\" after the modifier, so it still dangles.","D":"This makes \"the schedule\" the thing that trained: a dangling modifier."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'easy', -1, 'mcq', 'Text 1
Many home gardeners water their plants a little every day, believing that frequent watering keeps plants healthy.

Text 2
Horticulturist Ben Ito advises watering deeply but only once or twice a week. Shallow daily watering, he explains, encourages roots to stay near the surface, leaving plants vulnerable during dry spells, while deep watering encourages roots to grow downward.', 'Based on the texts, how would Ito (Text 2) most likely respond to the gardeners'' practice described in Text 1?', '[{"id":"A","text":"He would agree that plants need some water every day."},{"id":"B","text":"He would say that plants rarely need water at all."},{"id":"C","text":"He would recommend watering only in winter."},{"id":"D","text":"He would say that shallow daily watering can actually weaken plants."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Ito explains that shallow daily watering keeps roots near the surface and leaves plants vulnerable.', '{"A":"He recommends watering only once or twice a week.","B":"He recommends deep watering, not none.","C":"Seasons aren''t discussed."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'easy', -1, 'mcq', 'Text 1
Some teachers ban phones in class, arguing that the devices inevitably distract students from learning.

Text 2
Teacher Rosa Kim allows phones in her classroom, but only for specific tasks, such as looking up a word or photographing notes on the board. She found that once phones had a clear purpose, students rarely used them for games or messages.', 'Based on the texts, how would Kim (Text 2) most likely respond to the teachers'' argument in Text 1?', '[{"id":"A","text":"She would suggest that phones need not be distracting when their use is clearly limited."},{"id":"B","text":"She would agree that phones should always be banned."},{"id":"C","text":"She would argue that games help students learn."},{"id":"D","text":"She would say students should use phones whenever they wish."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Kim''s experience challenges "inevitably": with clear limits, phones weren''t a distraction.', '{"B":"She allows phones for set tasks.","C":"She found students rarely played games; she doesn''t recommend them.","D":"She limits phones to specific tasks."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'easy', -1, 'mcq', 'Text 1
Some city leaders believe that building more parking garages downtown will bring shoppers back to struggling local stores.

Text 2
Planner Dev Patel studied downtowns that added large parking garages. He found that the number of shoppers changed little, while downtowns that instead widened sidewalks and added benches and trees saw noticeably more visitors.', 'Based on the texts, how would Patel (Text 2) most likely respond to the city leaders'' belief in Text 1?', '[{"id":"A","text":"He would agree that garages are the best way to attract shoppers."},{"id":"B","text":"He would argue that downtowns should ban all cars."},{"id":"C","text":"He would claim that shoppers prefer garages to sidewalks."},{"id":"D","text":"He would doubt that adding parking alone would bring back shoppers."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Patel found garages did little, while walkable improvements drew more visitors.', '{"A":"His data showed garages changed little.","B":"He never proposes banning cars.","C":"His findings suggest the opposite."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'easy', -1, 'mcq', 'Text 1
Reading aloud to young children builds their vocabulary, because children hear words they would rarely encounter in everyday conversation.

Text 2
Reading aloud does matter, but researcher Ama Owusu found that the largest vocabulary gains came when adults paused to talk with children about the story, asking questions and explaining unfamiliar words.', 'Based on the texts, both authors would most likely agree with which statement?', '[{"id":"A","text":"Talking about a story matters more than reading it."},{"id":"B","text":"Children learn no words from everyday conversation."},{"id":"C","text":"Reading aloud should be replaced by conversation."},{"id":"D","text":"Reading aloud to young children can help build their vocabulary."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Both texts accept that reading aloud helps vocabulary. Text 2 adds that discussion increases the gains.', '{"A":"Text 1 doesn''t make this comparison.","B":"Text 1 says children rarely hear such words in conversation, not that they learn none.","C":"Text 2 says reading aloud matters."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'easy', -1, 'mcq', 'Text 1
A popular belief holds that goldfish have extremely short memories, lasting only a few seconds.

Text 2
Biologist Leo Marsh trained goldfish to push a small lever to receive food, but only at a certain time of day. Months later, after the lever had been removed and then returned, the fish still gathered at it at the trained time.', 'Based on the texts, how would Marsh (Text 2) most likely respond to the belief described in Text 1?', '[{"id":"A","text":"He would agree that goldfish forget within seconds."},{"id":"B","text":"He would say that goldfish cannot be trained."},{"id":"C","text":"He would claim that goldfish remember only colors."},{"id":"D","text":"He would say that his findings contradict the belief."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Remembering a trained behavior months later contradicts a memory of a few seconds.', '{"A":"His fish remembered for months.","B":"He trained them successfully.","C":"Colors weren''t tested."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'easy', -1, 'mcq', 'Text 1
Some popular diet guides recommend avoiding all dietary fats in order to stay healthy.

Text 2
Dietitian Noor Aziz explains that the body needs certain fats, such as those found in nuts and fish, in order to absorb some vitamins. She recommends limiting some types of fat rather than eliminating fat from the diet entirely.', 'Based on the texts, how would Aziz (Text 2) most likely respond to the recommendation in Text 1?', '[{"id":"A","text":"She would fully endorse avoiding all fats."},{"id":"B","text":"She would say that vitamins are unnecessary."},{"id":"C","text":"She would recommend eating only nuts and fish."},{"id":"D","text":"She would argue that avoiding all fats could be harmful."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Because some fats are needed to absorb vitamins, cutting out all fat could cause harm.', '{"A":"She says the body needs some fats.","B":"She says fats help the body absorb vitamins.","C":"Nuts and fish are examples, not a whole diet."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'easy', -1, 'mcq', 'Text 1
Local histories often describe the town''s first public library, which opened in 1902, as a gift from a single wealthy donor.

Text 2
Historian Clara Ruiz points out that the donor paid only for the library building. Town residents raised the money for books and staff themselves, through decades of bake sales, concerts, and small yearly subscriptions.', 'Based on the texts, how would Ruiz (Text 2) most likely respond to the description in Text 1?', '[{"id":"A","text":"She would agree that the donor funded everything."},{"id":"B","text":"She would say that the description leaves out residents'' major contributions."},{"id":"C","text":"She would argue that the library opened much earlier."},{"id":"D","text":"She would say that the donor opposed the library."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Ruiz shows residents funded much of the library, which the single-donor story omits.', '{"A":"She shows residents funded books and staff.","C":"The opening date isn''t disputed.","D":"The donor paid for the building."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'medium', 0, 'mcq', 'Text 1
Many economists argue that raising the price of gasoline through taxes will lead people to drive less.

Text 2
Economist Hal Brennan found that in the short term, people drive about the same amount when gas prices rise, since commutes cannot easily change. Over several years, however, people buy more efficient cars and move closer to work, and total driving falls.', 'Based on the texts, how would Brennan (Text 2) most likely respond to the economists'' argument in Text 1?', '[{"id":"A","text":"He would say that higher prices never affect driving."},{"id":"B","text":"He would say that driving falls immediately when prices rise."},{"id":"C","text":"He would say that the effect described in Text 1 may take years to appear."},{"id":"D","text":"He would argue that gas taxes should be lowered."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Brennan agrees that driving falls, but only gradually, as people change cars and homes.', '{"A":"Driving falls over several years.","B":"He found little short-term change.","D":"He makes no policy recommendation."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'medium', 0, 'mcq', 'Text 1
Critics have praised photographer Mina Cho''s portraits for capturing her subjects'' true personalities.

Text 2
Cho herself is skeptical of such praise. A portrait, she says, shows only how a person looked during one second in front of a camera, often while feeling self-conscious, and it reveals as much about the photographer''s choices as about the subject.', 'Based on the texts, how would Cho (Text 2) most likely respond to the critics'' praise in Text 1?', '[{"id":"A","text":"She would agree that her portraits reveal true personalities."},{"id":"B","text":"She would question whether a portrait can capture a subject''s true personality."},{"id":"C","text":"She would argue that self-conscious subjects make better portraits."},{"id":"D","text":"She would say that photographers make no choices."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Cho says a portrait records one self-conscious moment shaped by the photographer, not a person''s true self.', '{"A":"She is skeptical of that praise.","C":"She mentions self-consciousness as a limitation.","D":"She emphasizes the photographer''s choices."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'medium', 0, 'mcq', 'Text 1
Bike-share programs reduce car traffic by giving people an easy alternative to driving for short trips.

Text 2
A study of one city''s bike-share program found that most riders would otherwise have walked or taken a bus, not driven. The program still benefited riders by saving them time, the study''s authors noted, but its effect on car traffic was small.', 'Based on the texts, how would the study''s authors (Text 2) most likely respond to the claim in Text 1?', '[{"id":"A","text":"They would agree that bike-share greatly reduces car traffic."},{"id":"B","text":"They would say that bike-share has no benefits."},{"id":"C","text":"They would argue that buses should be eliminated."},{"id":"D","text":"They would say the program''s effect on car traffic may be smaller than claimed."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Most riders replaced walking or buses, not cars, so the effect on traffic was small.', '{"A":"They found the traffic effect was small.","B":"They note riders saved time.","C":"They make no recommendation about buses."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'medium', 0, 'mcq', 'Text 1
Some scientists propose planting very large numbers of trees to slow climate change, since trees absorb carbon dioxide as they grow.

Text 2
Ecologist Ruth Ndiaye supports tree planting but warns that planting trees in grasslands that never had forests can harm species adapted to open land and may even reduce the amount of carbon stored in the soil.', 'Based on the texts, how would Ndiaye (Text 2) most likely respond to the proposal in Text 1?', '[{"id":"A","text":"She would reject tree planting entirely."},{"id":"B","text":"She would deny that trees absorb carbon dioxide."},{"id":"C","text":"She would recommend planting trees mainly in grasslands."},{"id":"D","text":"She would support the idea but caution that where trees are planted matters."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Ndiaye supports planting but warns that planting in the wrong places can backfire.', '{"A":"She supports tree planting.","B":"She doesn''t dispute this.","C":"She warns against planting in natural grasslands."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'medium', 0, 'mcq', 'Text 1
Several older studies concluded that babies cannot recognize faces until they are several months old.

Text 2
Using newer equipment that precisely tracks where infants look, psychologist Ivan Petrov found that newborns only a few days old look longer at face-like patterns than at other shapes with the same brightness and size.', 'Based on the texts, how would Petrov (Text 2) most likely respond to the conclusion in Text 1?', '[{"id":"A","text":"He would say that newer methods suggest the ability may begin earlier than the older studies concluded."},{"id":"B","text":"He would agree that recognition begins only after several months."},{"id":"C","text":"He would argue that newborns cannot see shapes."},{"id":"D","text":"He would say that brightness explains the newborns'' behavior."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Petrov''s newborn data challenge the older conclusion, and better methods are the likely reason.', '{"B":"His newborns already preferred faces.","C":"They distinguished face-like patterns.","D":"He controlled for brightness."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'medium', 0, 'mcq', 'Text 1
Many people assume that working from home reduces collaboration among coworkers.

Text 2
Researchers at a design firm compared teams before and after a shift to remote work. Scheduled meetings stayed about as frequent as before, but brief, unplanned conversations dropped sharply, and employees reported fewer new ideas arising from chance encounters.', 'Based on the texts, how would the researchers (Text 2) most likely respond to the assumption in Text 1?', '[{"id":"A","text":"They would completely disagree, since meetings stayed frequent."},{"id":"B","text":"They would argue that remote work improved collaboration."},{"id":"C","text":"They would partly agree, noting that informal interactions declined even though scheduled ones did not."},{"id":"D","text":"They would say that nothing changed after the shift."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Their finding is mixed: formal collaboration held steady, but informal collaboration fell.', '{"A":"Informal conversations dropped sharply.","B":"Nothing suggests improvement.","D":"Unplanned conversations dropped."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'medium', 0, 'mcq', 'Text 1
A popular view holds that the ancient city of Varo was abandoned suddenly after an earthquake struck the region.

Text 2
Archaeologist Tess Morin notes that houses in Varo were emptied of valuables and their doors carefully sealed, and that the most recent coins found in the city date from decades before the earthquake.', 'Based on the texts, how would Morin (Text 2) most likely respond to the view in Text 1?', '[{"id":"A","text":"She would argue that the city was likely abandoned gradually and deliberately before the earthquake."},{"id":"B","text":"She would agree that people fled the moment the earthquake struck."},{"id":"C","text":"She would say that the earthquake never happened."},{"id":"D","text":"She would claim that the city was never inhabited."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Emptied, sealed houses and coins from decades earlier point to planned abandonment before the quake.', '{"B":"Sealed, emptied houses suggest planning, not panic.","C":"She dates the evidence relative to the earthquake rather than denying it.","D":"The houses and coins show people lived there."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'hard', 1, 'mcq', 'Text 1
Some literary scholars read the poet''s final collection as an expression of despair, pointing to its many images of winter and darkness.

Text 2
Scholar Imani Brooks notes that nearly every winter image in the collection is paired with a sign of return, such as buds beneath snow or a lamp lit at dusk. Read as a whole, she argues, the collection is less about loss than about endurance.', 'Based on the texts, how would Brooks (Text 2) most likely respond to the scholars'' reading in Text 1?', '[{"id":"A","text":"She would argue that the scholars overlook how the dark images are balanced by signs of renewal."},{"id":"B","text":"She would agree that the collection mainly expresses despair."},{"id":"C","text":"She would say that the poems contain no images of winter."},{"id":"D","text":"She would argue that the collection is about spring rather than endurance."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Brooks accepts that the winter imagery is there but shows it is paired with renewal, so the scholars'' reading is incomplete.', '{"B":"She reads the collection as about endurance.","C":"She acknowledges the winter images.","D":"She calls it about endurance, not spring."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'hard', 1, 'mcq', 'Text 1
Proponents of standardized admissions tests argue that the tests provide an objective measure that lets colleges compare students from very different high schools.

Text 2
Researcher Paul Venn agrees that a common measure is useful, but he found that at many colleges, high school grades predicted first-year success about as well as test scores did, and that combining the two predicted best of all.', 'Based on the texts, how would Venn (Text 2) most likely respond to the proponents'' argument in Text 1?', '[{"id":"A","text":"He would accept the value of a common measure but suggest that tests are most useful alongside grades."},{"id":"B","text":"He would argue that tests should replace grades entirely."},{"id":"C","text":"He would reject comparing students from different schools."},{"id":"D","text":"He would claim that grades are useless for predicting success."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Venn agrees in part (a common measure helps) but found grades and scores together predicted best.', '{"B":"Grades predicted about as well, and combining the two was best.","C":"He calls a common measure useful.","D":"Grades predicted well in his data."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'hard', 1, 'mcq', 'Text 1
Historians have often credited the invention of the printing press with rapidly spreading literacy across Europe.

Text 2
Historian Elena Varga observes that in many regions, literacy rates rose only slowly for two centuries after printing presses arrived, increasing sharply only when schooling became widely available.', 'Based on the texts, how would Varga (Text 2) most likely respond to the historians'' view in Text 1?', '[{"id":"A","text":"She would argue that printing alone may not explain the rise in literacy, which depended heavily on schooling."},{"id":"B","text":"She would agree that printing caused literacy to spread rapidly."},{"id":"C","text":"She would claim that printing presses arrived only recently."},{"id":"D","text":"She would argue that schooling reduced literacy."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Varga links the sharp rise in literacy to schooling, not to printing alone.', '{"B":"She found literacy rose slowly after printing.","C":"She says presses arrived two centuries before the sharp rise.","D":"Literacy rose with schooling."}'::jsonb),
  ('rw.cs.crosstext', 'rw.cs.crosstext.respond', 'hard', 1, 'mcq', 'Text 1
Many zoologists hold that animals raised in captivity lose the hunting skills of their wild relatives.

Text 2
In a study by zoologist Kai Lund, captive-born otters released into a large enclosure stocked with live fish caught prey within days, though less efficiently than wild otters at first. After a month, the difference had largely disappeared.', 'Based on the texts, how would Lund (Text 2) most likely respond to the view in Text 1?', '[{"id":"A","text":"He would suggest that such skills may be dormant rather than lost and can recover quickly."},{"id":"B","text":"He would agree that captive animals permanently lose hunting skills."},{"id":"C","text":"He would argue that captive otters hunt better than wild ones."},{"id":"D","text":"He would say that otters do not hunt fish."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The otters were weaker at first but caught up within a month, which suggests the skills were dormant, not lost.', '{"B":"The otters caught up within a month.","C":"They were less efficient at first and only caught up later.","D":"The otters caught fish."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.purpose', 'easy', -1, 'mcq', 'Every spring, volunteers at the Millbrook Nature Center count the frogs calling from the center''s ponds. The counts help staff track whether the frog population is stable. This year, volunteers will also record water temperature, so that staff can study how warmer springs affect frog activity.', 'Which choice best states the main purpose of the text?', '[{"id":"A","text":"To explain what a volunteer frog count involves and why it is done"},{"id":"B","text":"To argue that frogs are disappearing everywhere"},{"id":"C","text":"To describe the history of the nature center"},{"id":"D","text":"To persuade readers to visit the ponds"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The text describes the count, its purpose, and this year''s addition.', '{"B":"The text makes no claim about frogs everywhere.","C":"The center''s history isn''t discussed.","D":"The text informs rather than persuades."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.function', 'easy', -1, 'mcq', 'Many people think of pigeons as city birds. However, wild pigeons originally lived on rocky sea cliffs. City buildings, with their ledges and stone walls, resemble those cliffs, which may explain why pigeons thrive in cities.', 'Which choice best describes the function of the third sentence in the overall structure of the text?', '[{"id":"A","text":"It contradicts the claim made in the first sentence."},{"id":"B","text":"It introduces a topic unrelated to pigeons."},{"id":"C","text":"It offers a possible reason for a pattern described earlier in the text."},{"id":"D","text":"It gives an example of a rocky sea cliff."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The third sentence explains why pigeons thrive in cities: buildings resemble their original cliff homes.', '{"A":"It supports, rather than contradicts, the idea that pigeons do well in cities.","B":"It''s directly about pigeons.","D":"It compares buildings to cliffs; it doesn''t give an example of a cliff."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.purpose', 'easy', -1, 'mcq', 'Chef Ana Lopes keeps a vegetable garden behind her restaurant. Each morning she checks what is ripe before writing the day''s menu, which changes almost daily. Lopes says this habit forces her to invent new dishes and keeps her cooking from becoming routine.', 'Which choice best states the main purpose of the text?', '[{"id":"A","text":"To describe a chef''s approach to planning her menu and its benefit"},{"id":"B","text":"To argue that every restaurant should have a garden"},{"id":"C","text":"To list the vegetables Lopes grows"},{"id":"D","text":"To compare Lopes''s restaurant with others"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The text explains Lopes''s garden-based menu planning and why she values it.', '{"B":"The text describes one chef; it doesn''t argue for all restaurants.","C":"No vegetables are listed.","D":"No other restaurants are mentioned."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.function', 'easy', -1, 'mcq', 'Wind turbines are usually placed on land, but some engineers now build them at sea. Winds over the ocean tend to be stronger and steadier than winds over land. As a result, offshore turbines can generate more electricity.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id":"A","text":"It describes a drawback of offshore turbines."},{"id":"B","text":"It contradicts the first sentence."},{"id":"C","text":"It summarizes the text as a whole."},{"id":"D","text":"It gives a reason that supports the claim in the third sentence."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Stronger, steadier ocean winds explain why offshore turbines produce more electricity ("As a result").', '{"A":"Stronger winds are an advantage.","B":"It explains the first sentence''s trend rather than contradicting it.","C":"It''s a supporting reason, not a summary."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.purpose', 'easy', -1, 'mcq', 'Before printed maps were common, sailors in some regions memorized long chants that described coastlines, currents, and landmarks in the order they would appear. Reciting a chant during a voyage helped sailors keep track of where they were.', 'Which choice best states the main purpose of the text?', '[{"id":"A","text":"To argue that chants are more accurate than maps"},{"id":"B","text":"To describe how some sailors used memorized chants to navigate"},{"id":"C","text":"To explain how printed maps were invented"},{"id":"D","text":"To describe the music sailors enjoyed"}]'::jsonb, '{"choice":"B"}'::jsonb, 'The text explains what the chants contained and how they helped sailors navigate.', '{"A":"No comparison of accuracy is made.","C":"The invention of maps is not explained.","D":"The chants served navigation, not entertainment."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.function', 'easy', -1, 'mcq', 'The museum''s new exhibit features objects from everyday life in the 1950s. Visitors can see a kitchen, a radio, and a child''s bedroom furnished exactly as they would have been. Curators hope the exhibit will help younger visitors imagine their grandparents'' childhoods.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id":"A","text":"It gives examples of what the exhibit includes."},{"id":"B","text":"It explains why the exhibit was created."},{"id":"C","text":"It criticizes the exhibit''s design."},{"id":"D","text":"It describes the history of the museum."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The kitchen, radio, and bedroom are examples of the "objects from everyday life" the first sentence mentions.', '{"B":"The purpose comes in the third sentence.","C":"No criticism is offered.","D":"The museum''s history isn''t discussed."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.purpose', 'easy', -1, 'mcq', 'Most of the moon''s surface is covered in a layer of fine dust. Because the moon has almost no atmosphere, there is no wind to blow this dust away, so footprints left by astronauts decades ago are most likely still visible today.', 'Which choice best states the main purpose of the text?', '[{"id":"A","text":"To describe how astronauts trained for missions"},{"id":"B","text":"To argue that the moon has strong winds"},{"id":"C","text":"To compare moon dust with sand on Earth"},{"id":"D","text":"To explain why footprints on the moon are likely to last a long time"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The text links the moon''s dust and lack of wind to footprints lasting for decades.', '{"A":"Training isn''t discussed.","B":"The text says there is no wind.","C":"Earth''s sand isn''t mentioned."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.overall', 'medium', 0, 'mcq', 'Some economists predicted that a new highway would bring businesses to the small town of Lyle. When the highway opened, a few gas stations and restaurants appeared near the exit. Yet the town''s main street, now bypassed by travelers, lost several shops. Overall, the town''s business activity changed less than either supporters or opponents had predicted.', 'Which choice best describes the overall structure of the text?', '[{"id":"A","text":"It describes a problem and then proposes a solution."},{"id":"B","text":"It compares two towns and argues that one is better."},{"id":"C","text":"It presents a prediction, describes mixed results, and then offers an overall assessment."},{"id":"D","text":"It presents a theory and then provides evidence that proves it."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The text moves from a prediction, to gains and losses, to an overall judgment.', '{"A":"No solution is proposed.","B":"Only one town is discussed.","D":"The results only partly matched the prediction."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.function', 'medium', 0, 'mcq', 'Researchers once believed that the giant squid was a sluggish animal that drifted slowly in deep water. Then, in 2004, a research team photographed a giant squid attacking bait in the wild. The images showed the squid moving quickly and seizing the bait with its long tentacles.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id":"A","text":"It restates the earlier belief in different words."},{"id":"B","text":"It introduces evidence that challenges an earlier belief."},{"id":"C","text":"It describes the habitat where giant squid live."},{"id":"D","text":"It explains why the squid was thought to be sluggish."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The 2004 photographs are new evidence that leads into the third sentence''s challenge to the "sluggish" belief.', '{"A":"It introduces new evidence rather than restating.","C":"It''s about an observation, not habitat.","D":"It doesn''t explain the old belief."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.purpose', 'medium', 0, 'mcq', 'Grandmother kept her recipes in no book. She cooked by memory, adding a pinch of this and a handful of that, and when we asked for exact amounts she only laughed. Years later, trying to recreate her soup, I realized the recipe had lived in her hands, not in any measurement.', 'Which choice best states the main purpose of the text?', '[{"id":"A","text":"To provide a recipe for the grandmother''s soup"},{"id":"B","text":"To criticize the grandmother for refusing to share"},{"id":"C","text":"To describe the narrator''s career as a chef"},{"id":"D","text":"To show how the narrator came to understand the nature of the grandmother''s cooking"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The text builds to the narrator''s realization that the recipe existed only in the grandmother''s practiced hands.', '{"A":"No recipe is given.","B":"Her laughter is fond, not a refusal being criticized.","C":"The narrator''s career isn''t mentioned."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.function', 'medium', 0, 'mcq', 'Many coastal cities protect themselves from storms with concrete sea walls. Such walls can be effective, but they also prevent beaches from naturally replenishing their sand. Some cities are therefore experimenting with "living shorelines" of marsh grasses and oyster reefs, which absorb wave energy while preserving natural processes.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id":"A","text":"It argues that sea walls never work."},{"id":"B","text":"It describes how oyster reefs grow."},{"id":"C","text":"It states the text''s final conclusion."},{"id":"D","text":"It identifies a drawback that motivates the alternative described next."}]'::jsonb, '{"choice":"D"}'::jsonb, 'The sea walls'' drawback explains why cities are "therefore" trying living shorelines.', '{"A":"It grants that walls \"can be effective.\"","B":"Oyster reefs come later and their growth isn''t described.","C":"The text ends with the alternative, not this sentence."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.overall', 'medium', 0, 'mcq', 'In the nineteenth century, many doctors dismissed the idea that washing hands could prevent disease. A few physicians who insisted on handwashing reported far fewer infections among their patients, but their findings were often ignored. Only after scientists identified germs as a cause of disease did handwashing become standard practice.', 'Which choice best describes the overall structure of the text?', '[{"id":"A","text":"It argues that doctors today still ignore handwashing."},{"id":"B","text":"It explains in detail how germs were discovered."},{"id":"C","text":"It describes resistance to a practice, early evidence for it, and its eventual acceptance."},{"id":"D","text":"It compares two different medical treatments."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The text traces a sequence: dismissal, ignored evidence, then acceptance once germs were understood.', '{"A":"The text is about the past.","B":"The discovery of germs is mentioned, not explained.","D":"Only one practice is discussed."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.function', 'hard', 1, 'mcq', 'Critics often praise novelist Iris Kade for her vivid settings. Yet her settings are rarely described directly. Instead, readers learn about a place through what characters notice, such as the sticky door of a café or a neighbor''s radio through a wall, so that the setting emerges from the characters'' attention rather than from the narrator''s descriptions.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id":"A","text":"It introduces a qualification that the rest of the text explains."},{"id":"B","text":"It contradicts the critics'' praise and argues that the settings are weak."},{"id":"C","text":"It provides an example of one of Kade''s vivid descriptions."},{"id":"D","text":"It summarizes Kade''s career."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The "Yet" sentence adds a surprising qualification (settings are seldom described directly), and the next sentence explains how they come through anyway.', '{"B":"It doesn''t call the settings weak; it explains how they work.","C":"The examples come in the third sentence.","D":"Kade''s career isn''t discussed."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.overall', 'hard', 1, 'mcq', 'For years I measured my running by speed, logging every mile and comparing each week to the last. Then an injury forced me to walk for three months. Walking, I noticed the street I had run down a thousand times: its gardens, its cracked steps, the dog that waited at one gate. When I returned to running, I left my watch at home.', 'Which choice best describes the overall structure of the text?', '[{"id":"A","text":"It argues that walking is better exercise than running."},{"id":"B","text":"It compares two different neighborhoods."},{"id":"C","text":"It describes a habit, an interruption that changed the narrator''s perspective, and a resulting change in behavior."},{"id":"D","text":"It explains how to recover from a running injury."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The text moves from an old habit, to an injury that changed what the narrator noticed, to running without a watch.', '{"A":"No argument about exercise is made.","B":"Only one street is described.","D":"Recovery methods aren''t discussed."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.purpose', 'hard', 1, 'mcq', 'Some historians treat the diaries of nineteenth-century travelers as reliable records of the places they visited. Historian Sara Moen urges caution. Travelers, she notes, often wrote with publication in mind, exaggerating dangers to seem adventurous and borrowing descriptions from earlier books they had read.', 'Which choice best states the main purpose of the text?', '[{"id":"A","text":"To argue that travel diaries should never be studied"},{"id":"B","text":"To present a historian''s reasons for questioning a type of historical source"},{"id":"C","text":"To describe a famous nineteenth-century journey"},{"id":"D","text":"To explain how travel diaries were published"}]'::jsonb, '{"choice":"B"}'::jsonb, 'The text gives Moen''s reasons why travel diaries may be unreliable.', '{"A":"Moen urges caution, not abandonment.","C":"No particular journey is described.","D":"Publishing methods aren''t explained."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.function', 'hard', 1, 'mcq', 'Glass is a solid at room temperature. Nevertheless, a popular story claims that old church windows are thicker at the bottom because glass slowly flows downward over centuries. In fact, the uneven thickness likely came from how window glass was made at the time, and installers often placed the thicker edge at the bottom.', 'Which choice best describes the function of the second sentence in the overall structure of the text?', '[{"id":"A","text":"It provides evidence for the claim in the first sentence."},{"id":"B","text":"It explains how glass is manufactured."},{"id":"C","text":"It states the text''s main conclusion."},{"id":"D","text":"It presents a common misconception that the text then corrects."}]'::jsonb, '{"choice":"D"}'::jsonb, 'The second sentence states the popular belief, and "In fact" introduces the correction.', '{"A":"It describes a story that conflicts with the first sentence.","B":"Manufacturing comes in the third sentence.","C":"The conclusion is the correction in the third sentence."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.function', 'hard', 1, 'mcq', 'When the city of Norvale planted thousands of street trees, officials emphasized the shade the trees would provide. A later study found an unexpected additional effect: blocks with more trees reported fewer complaints about noise, perhaps because leaves absorb sound or because greenery makes residents less bothered by it. The study''s authors note that they cannot yet tell which explanation is correct.', 'Which choice best describes the function of the third sentence in the overall structure of the text?', '[{"id":"A","text":"It acknowledges a limitation in what the study shows."},{"id":"B","text":"It rejects both possible explanations."},{"id":"C","text":"It restates the officials'' original goals."},{"id":"D","text":"It provides new evidence supporting one explanation."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The final sentence admits that the study can''t distinguish between the two explanations.', '{"B":"It says they can''t choose between the explanations, not that both are wrong.","C":"The officials'' goals come in the first sentence.","D":"It offers no new evidence."}'::jsonb),
  ('rw.cs.structure', 'rw.cs.structure.overall', 'hard', 1, 'mcq', 'In the mountain village of Selva Alta, farmers once grew dozens of potato varieties. As markets began paying more for a few uniform types, many farmers switched, and the older varieties nearly vanished. Recently, a farmers'' cooperative has begun selling the rare varieties to restaurants, which value their unusual colors and flavors, giving farmers a reason to plant them again.', 'Which choice best describes the overall structure of the text?', '[{"id":"A","text":"It describes a decline in crop diversity, its cause, and a development that may reverse it."},{"id":"B","text":"It argues that restaurants should buy only rare potatoes."},{"id":"C","text":"It compares potato farming in two different villages."},{"id":"D","text":"It explains how potatoes were first domesticated."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The text traces a loss of varieties, its market-driven cause, and a new market that may bring them back.', '{"B":"No argument is made about what restaurants should do.","C":"Only one village is discussed.","D":"Domestication isn''t mentioned."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'easy', -1, 'mcq', 'The new bridge over the river was designed to be ______: engineers expect it to withstand strong earthquakes and heavy traffic for more than a century without major repairs.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"temporary"},{"id":"B","text":"fragile"},{"id":"C","text":"durable"},{"id":"D","text":"decorative"}]'::jsonb, '{"choice":"C"}'::jsonb, 'Withstanding earthquakes and lasting a century describe something durable.', '{"A":"Lasting a century contradicts \"temporary.\"","B":"Withstanding earthquakes contradicts \"fragile.\"","D":"The text is about strength, not appearance."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'easy', -1, 'mcq', 'Because the assembly instructions were so ______, every team in the workshop put the shelves together correctly on the first try, and no one needed to ask the instructor for help.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"clear"},{"id":"B","text":"vague"},{"id":"C","text":"outdated"},{"id":"D","text":"colorful"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Everyone succeeding without help shows the instructions were clear.', '{"B":"Vague instructions would cause mistakes.","C":"Outdated instructions wouldn''t explain the success.","D":"Color doesn''t explain why everyone succeeded."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.meaning', 'easy', -1, 'mcq', 'The music festival drew a modest crowd in its first year, but word spread quickly. By its third year, organizers had to rent a field twice as large to hold everyone who came.', 'As used in the text, what does the word "modest" most nearly mean?', '[{"id":"A","text":"humble"},{"id":"B","text":"shy"},{"id":"C","text":"fairly small"},{"id":"D","text":"inexpensive"}]'::jsonb, '{"choice":"C"}'::jsonb, 'The contrast with later crowds that needed a larger field shows that "modest" means fairly small.', '{"A":"\"Humble\" describes people''s attitudes, not crowd size.","B":"\"Shy\" describes a person''s manner.","D":"The text is about size, not cost."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'easy', -1, 'mcq', 'Scientists were ______ to find frogs living deep inside the cave, since they had assumed that the cave''s air and water were far too cold for any amphibians to survive there.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"relieved"},{"id":"B","text":"reluctant"},{"id":"C","text":"unable"},{"id":"D","text":"surprised"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Finding frogs where they assumed none could live would surprise them.', '{"A":"Nothing suggests they had hoped to find frogs.","B":"\"Reluctant\" means unwilling, which doesn''t fit.","C":"They did find the frogs."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'easy', -1, 'mcq', 'Although the two paintings look ______ at first glance, close inspection reveals dozens of small differences in color, brushwork, and the placement of figures in the background.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"identical"},{"id":"B","text":"unrelated"},{"id":"C","text":"damaged"},{"id":"D","text":"colorful"}]'::jsonb, '{"choice":"A"}'::jsonb, '"Although" contrasts a first impression with hidden differences, so the paintings look identical at first.', '{"B":"\"Although\" sets up a contrast with the differences, so they must look alike at first.","C":"Damage has nothing to do with the contrast.","D":"Color doesn''t set up the contrast with differences."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'medium', 0, 'mcq', 'The committee''s decision was ______: it announced that it would not reconsider the proposal, no matter how many letters or petitions residents sent in the coming months.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"tentative"},{"id":"B","text":"popular"},{"id":"C","text":"final"},{"id":"D","text":"confusing"}]'::jsonb, '{"choice":"C"}'::jsonb, 'A decision that won''t be reconsidered is final.', '{"A":"Refusing to reconsider is the opposite of tentative.","B":"Nothing indicates public approval; residents seem to object.","D":"The decision is stated plainly."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.meaning', 'medium', 0, 'mcq', 'The senator''s speech was full of sweeping promises, but reporters noted that it offered few concrete plans explaining how any of those promises would actually be kept.', 'As used in the text, what does the word "concrete" most nearly mean?', '[{"id":"A","text":"specific"},{"id":"B","text":"made of cement"},{"id":"C","text":"solid and heavy"},{"id":"D","text":"permanent"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Contrasted with "sweeping promises," concrete plans are specific ones.', '{"B":"That is the literal meaning, not the one used here.","C":"Plans can''t be physically heavy.","D":"The contrast is with vagueness, not with change."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'medium', 0, 'mcq', 'Rather than ______ the author''s claims, the reviewer tested each one, checking the cited sources and repeating the key calculations herself before writing a word of her review.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"accepting"},{"id":"B","text":"verifying"},{"id":"C","text":"publishing"},{"id":"D","text":"inventing"}]'::jsonb, '{"choice":"A"}'::jsonb, '"Rather than" contrasts testing the claims with simply accepting them.', '{"B":"Testing the claims is verifying them, so \"rather than verifying\" contradicts the text.","C":"Publishing doesn''t contrast with testing.","D":"The claims were the author''s, not the reviewer''s."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'medium', 0, 'mcq', 'Early critics found the composer''s music ______, complaining that its harsh, clashing chords were unpleasant to hear; today, those same chords are admired as bold and inventive.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"soothing"},{"id":"B","text":"familiar"},{"id":"C","text":"grating"},{"id":"D","text":"brief"}]'::jsonb, '{"choice":"C"}'::jsonb, '"Grating" means irritating to hear, which matches the complaint about harsh, clashing chords.', '{"A":"Harsh chords are the opposite of soothing.","B":"The complaint is about harshness, not familiarity.","D":"Length is never discussed."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.meaning', 'medium', 0, 'mcq', 'Researchers hoped the new drought-resistant wheat would thrive in dry regions, but in early field trials it failed to take hold, producing only weak, scattered plants.', 'As used in the text, what does the phrase "take hold" most nearly mean?', '[{"id":"A","text":"become established"},{"id":"B","text":"grab firmly"},{"id":"C","text":"take control"},{"id":"D","text":"be harvested"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The weak, scattered plants show the wheat failed to become established.', '{"B":"That is the literal meaning, not the one used for plants.","C":"Crops don''t take control.","D":"Harvest comes later; the plants never got established."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'medium', 0, 'mcq', 'The documentary takes a ______ approach to its controversial subject, presenting the strongest evidence on each side of the debate without telling viewers which side to believe.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"biased"},{"id":"B","text":"balanced"},{"id":"C","text":"humorous"},{"id":"D","text":"careless"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Presenting both sides without taking a position is a balanced approach.', '{"A":"Presenting both sides fairly is the opposite of biased.","C":"Tone isn''t the point here.","D":"Presenting the strongest evidence is careful, not careless."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'medium', 0, 'mcq', 'Though the startup''s founders were confident in their product, investors remained ______, waiting to see a full year of sales figures before committing any money to the company.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"eager"},{"id":"B","text":"enthusiastic"},{"id":"C","text":"cautious"},{"id":"D","text":"indifferent"}]'::jsonb, '{"choice":"C"}'::jsonb, 'Waiting for evidence before investing describes caution.', '{"A":"Eager investors wouldn''t wait a year.","B":"Waiting before committing doesn''t show enthusiasm.","D":"Waiting for sales figures shows interest, so they weren''t indifferent."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'hard', 1, 'mcq', 'Historian Amara Diallo''s account of the 1912 textile strike is notably ______: she draws on letters from workers, factory owners, and city officials alike, giving careful attention to each group''s perspective.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"partisan"},{"id":"B","text":"cursory"},{"id":"C","text":"evenhanded"},{"id":"D","text":"speculative"}]'::jsonb, '{"choice":"C"}'::jsonb, 'Giving each group''s view careful attention makes the account evenhanded, meaning fair to all sides.', '{"A":"Partisan means favoring one side.","B":"Cursory means hasty, but her attention is careful.","D":"Her account rests on letters, not speculation."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'hard', 1, 'mcq', 'The poet''s late work is often described as ______; after decades of elaborate imagery, she began writing short, plain lines that avoid ornament of any kind.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"lavish"},{"id":"B","text":"whimsical"},{"id":"C","text":"obscure"},{"id":"D","text":"austere"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Short, plain, unornamented lines are austere, meaning stark and simple.', '{"A":"Lavish describes her earlier elaborate style.","B":"Nothing suggests playfulness.","C":"Plain lines are not hard to understand."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'hard', 1, 'mcq', 'Some economists argue that the policy''s benefits have been ______: the predicted rise in employment did occur, but it was far smaller than the policy''s supporters had claimed.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"overstated"},{"id":"B","text":"ignored"},{"id":"C","text":"understated"},{"id":"D","text":"fabricated"}]'::jsonb, '{"choice":"A"}'::jsonb, 'A real but smaller-than-claimed benefit was overstated.', '{"B":"Supporters promoted the benefits rather than ignoring them.","C":"The actual benefit was smaller than claimed, not larger.","D":"Employment did rise, so the benefits weren''t invented."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.meaning', 'hard', 1, 'mcq', 'In her review, the critic conceded that the film''s pacing was slow, but she argued that its patient camera work rewarded viewers willing to sit with each scene.', 'As used in the text, what does the word "conceded" most nearly mean?', '[{"id":"A","text":"surrendered"},{"id":"B","text":"refused"},{"id":"C","text":"celebrated"},{"id":"D","text":"admitted"}]'::jsonb, '{"choice":"D"}'::jsonb, 'She admitted a weakness (slow pacing) before making her main argument.', '{"A":"She didn''t give up her argument; she went on to defend the film.","B":"She acknowledged the point rather than refusing it.","C":"Slow pacing is presented as a weakness she grants."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'hard', 1, 'mcq', 'The researchers'' conclusion about the birds'' migration routes was ______, since it rested on observations of only three animals tracked during a single, unusually mild season.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"tenuous"},{"id":"B","text":"definitive"},{"id":"C","text":"unanimous"},{"id":"D","text":"irrelevant"}]'::jsonb, '{"choice":"A"}'::jsonb, 'A conclusion based on three animals in one season is tenuous, meaning weakly supported.', '{"B":"So little data can''t support a definitive conclusion.","C":"The text says nothing about agreement among researchers.","D":"The weakness is the evidence, not relevance."}'::jsonb),
  ('rw.cs.wic', 'rw.cs.wic.choice', 'hard', 1, 'mcq', 'Far from being ______, the novel''s ending had been planned from the start: early chapters contain small hints that make the final twist seem inevitable on a second reading.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id":"A","text":"predictable"},{"id":"B","text":"inevitable"},{"id":"C","text":"memorable"},{"id":"D","text":"arbitrary"}]'::jsonb, '{"choice":"D"}'::jsonb, '"Far from" sets up a contrast with "planned from the start," which is the opposite of arbitrary.', '{"A":"\"Far from being predictable\" doesn''t contrast logically with \"planned from the start.\"","B":"The text says the ending seems inevitable, so \"far from being inevitable\" contradicts it.","C":"Being planned doesn''t contrast with being memorable."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'easy', -1, 'mcq', 'While researching a topic, a student has taken the following notes:
• Mount Corva is a volcano on the island of Isla Verde.
• It rises 2,940 meters above sea level.
• It last erupted in 1891.
• Scientists monitor it with seismic sensors.', 'The student wants to introduce Mount Corva to an audience unfamiliar with it. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"It last erupted in 1891."},{"id":"B","text":"Mount Corva, a 2,940-meter volcano on Isla Verde, last erupted in 1891."},{"id":"C","text":"Isla Verde is an island."},{"id":"D","text":"Scientists monitor seismic sensors."}]'::jsonb, '{"choice":"B"}'::jsonb, 'This choice names the volcano and gives its location, height, and last eruption.', '{"A":"This doesn''t name or describe the volcano for a new audience.","C":"This doesn''t mention the volcano.","D":"This misstates the notes and doesn''t introduce the volcano."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'easy', -1, 'mcq', 'While researching a topic, a student has taken the following notes:
• The Lark is a wooden sailing ship built in 1902.
• It is 34 meters long.
• It was fully restored in 2015.
• It now serves as a floating museum in Port Ellis.', 'The student wants to emphasize how the ship is used today. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"The Lark was built in 1902."},{"id":"B","text":"Today, the restored Lark serves as a floating museum in Port Ellis."},{"id":"C","text":"The Lark is 34 meters long."},{"id":"D","text":"The Lark is a wooden sailing ship."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Only this choice states the ship''s present use.', '{"A":"This gives the ship''s age, not its current use.","C":"This gives its size, not its current use.","D":"This describes the ship, not its current use."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'easy', -1, 'mcq', 'While researching a topic, a student has taken the following notes:
• Mira Sol published her first novel, The Salt Road, in 2011.
• The novel won the Hale Prize for fiction.
• It is set in a desert trading town.
• It follows a family of merchants over three generations.', 'The student wants to identify the novel''s setting. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"The Salt Road won the Hale Prize for fiction."},{"id":"B","text":"Mira Sol published The Salt Road in 2011."},{"id":"C","text":"Mira Sol''s novel The Salt Road is set in a desert trading town."},{"id":"D","text":"The Salt Road follows three generations of merchants."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Only this choice names the setting.', '{"A":"This gives an award, not the setting.","B":"This gives a date, not the setting.","D":"This describes the plot, not the setting."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'easy', -1, 'mcq', 'While researching a topic, a student has taken the following notes:
• Alder cheese is made from cow''s milk.
• Alder cheese is aged for three months.
• Bryn cheese is made from goat''s milk.
• Bryn cheese is aged for two years.', 'The student wants to compare how long the two cheeses are aged. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Alder cheese is made from cow''s milk, and Bryn cheese from goat''s milk."},{"id":"B","text":"Bryn cheese is aged for two years."},{"id":"C","text":"Alder cheese is aged for three months, while Bryn cheese is aged for two years."},{"id":"D","text":"Both cheeses are aged."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Only this choice states both aging times side by side.', '{"A":"This compares milk, not aging time.","B":"This gives only one aging time.","D":"This gives neither aging time."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'easy', -1, 'mcq', 'While researching a topic, a student has taken the following notes:
• The Kettle Falls Dam was completed in 1958.
• It created Lake Ardis.
• The dam supplies electricity to about 200,000 homes.
• The dam is 120 meters tall.', 'The student wants to explain a benefit that the dam provides to residents. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"The Kettle Falls Dam supplies electricity to about 200,000 homes."},{"id":"B","text":"The Kettle Falls Dam was completed in 1958."},{"id":"C","text":"The Kettle Falls Dam is 120 meters tall."},{"id":"D","text":"The Kettle Falls Dam created Lake Ardis."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Supplying electricity to homes is a direct benefit to residents.', '{"B":"A completion date isn''t a benefit.","C":"Height isn''t a benefit.","D":"This names the lake without saying how it benefits residents."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'easy', -1, 'mcq', 'While researching a topic, a student has taken the following notes:
• Rui Matsuda is a painter born in 1952.
• He is known for paintings of rainy city streets.
• His painting Gray Harbor was completed in 1987.
• Gray Harbor hangs in the City Art Museum.', 'The student wants to name a specific work by Matsuda and say where it can be seen. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Rui Matsuda is known for paintings of rainy city streets."},{"id":"B","text":"Rui Matsuda was born in 1952."},{"id":"C","text":"Gray Harbor was completed in 1987."},{"id":"D","text":"Rui Matsuda''s painting Gray Harbor can be seen at the City Art Museum."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Only this choice names a work and its location.', '{"A":"This names no specific work or location.","B":"This gives neither a work nor a location.","C":"This names a work but not where it can be seen."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'easy', -1, 'mcq', 'While researching a topic, a student has taken the following notes:
• The North Trail is 4 miles long and rated easy.
• The North Trail passes a waterfall.
• The Ridge Trail is 9 miles long and rated difficult.
• The Ridge Trail offers views of the valley.', 'The student wants to recommend a trail to a beginning hiker. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"The Ridge Trail offers views of the valley."},{"id":"B","text":"The Ridge Trail is 9 miles long and rated difficult."},{"id":"C","text":"Beginners may prefer the North Trail, an easy 4-mile route that passes a waterfall."},{"id":"D","text":"The North Trail and the Ridge Trail are both in the park."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The easy, shorter trail suits a beginner, and this choice says so.', '{"A":"This promotes the harder trail without addressing beginners.","B":"This describes the difficult trail, which doesn''t suit beginners.","D":"This isn''t in the notes and makes no recommendation."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'medium', 0, 'mcq', 'While researching a topic, a student has taken the following notes:
• Honeybees perform a "waggle dance" after finding food.
• The angle of the dance shows the direction of the food relative to the sun.
• The length of the waggle shows the distance to the food.
• The dance was first decoded by scientist Karl von Frisch.', 'The student wants to explain what information the waggle dance conveys. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"The waggle dance was first decoded by Karl von Frisch."},{"id":"B","text":"Through the angle and length of its waggle dance, a honeybee shows other bees the direction of and distance to food."},{"id":"C","text":"Honeybees perform a waggle dance after finding food."},{"id":"D","text":"The angle of the dance relates to the sun."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Only this choice explains both pieces of information the dance conveys.', '{"A":"This is about who decoded the dance, not what it conveys.","C":"This says when bees dance, not what the dance conveys.","D":"This is incomplete; it omits direction to food and distance."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'medium', 0, 'mcq', 'While researching a topic, a student has taken the following notes:
• Eastside Library holds 40,000 books and is open six days a week.
• Westside Library holds 65,000 books and is open seven days a week.
• Both libraries offer free after-school tutoring.', 'The student wants to emphasize a similarity between the two libraries. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Westside Library holds 25,000 more books than Eastside Library."},{"id":"B","text":"Eastside Library is open six days a week, and Westside is open seven."},{"id":"C","text":"Both the Eastside and Westside libraries offer free after-school tutoring."},{"id":"D","text":"Westside Library holds 65,000 books."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Free tutoring is the only feature the notes say both libraries share.', '{"A":"This emphasizes a difference.","B":"This emphasizes a difference.","D":"This describes only one library."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'medium', 0, 'mcq', 'While researching a topic, a student has taken the following notes:
• Researchers surveyed 500 commuters about their satisfaction with their daily commute.
• Cyclists reported the highest satisfaction.
• Drivers reported the lowest satisfaction.
• Bus riders reported satisfaction between the two.', 'The student wants to present the study''s findings about drivers and cyclists. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Bus riders reported satisfaction between that of cyclists and drivers."},{"id":"B","text":"In a survey of 500 commuters, cyclists were the most satisfied with their commutes and drivers were the least."},{"id":"C","text":"Researchers surveyed 500 commuters."},{"id":"D","text":"Cyclists ride bicycles to work."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Only this choice reports the results for both drivers and cyclists.', '{"A":"This focuses on bus riders.","C":"This gives no findings.","D":"This isn''t a finding from the notes."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'medium', 0, 'mcq', 'While researching a topic, a student has taken the following notes:
• Marine biologist Ada Nwosu studied coral reefs from 2019 to 2020.
• She tracked corals that had lost their color after a heat wave.
• Some corals fully recovered within a year.
• Corals in cooler, deeper water recovered fastest.', 'The student wants to present the study''s main finding. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Nwosu studied coral reefs from 2019 to 2020."},{"id":"B","text":"Nwosu found that some heat-damaged corals recovered within a year, with those in cooler, deeper water recovering fastest."},{"id":"C","text":"Nwosu tracked corals after a heat wave."},{"id":"D","text":"Corals can lose their color."}]'::jsonb, '{"choice":"B"}'::jsonb, 'This choice states what Nwosu found: recovery, and where it was fastest.', '{"A":"This gives the study''s dates, not its finding.","C":"This describes the method, not the finding.","D":"This is background, not the finding."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'medium', 0, 'mcq', 'While researching a topic, a student has taken the following notes:
• The town of Elden had a population of 4,200 in 1990.
• Its population reached 9,800 in 2020.
• Much of the growth came from new technology jobs.
• Elden is located along the Pell River.', 'The student wants to emphasize how much the town grew. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Elden is located along the Pell River."},{"id":"B","text":"Elden''s population more than doubled between 1990 and 2020, rising from 4,200 to 9,800."},{"id":"C","text":"Much of Elden''s growth came from technology jobs."},{"id":"D","text":"Elden had a population of 4,200 in 1990."}]'::jsonb, '{"choice":"B"}'::jsonb, 'This choice gives both figures and stresses that the population more than doubled (9,800 is over twice 4,200).', '{"A":"Location says nothing about growth.","C":"This gives the cause, not how much the town grew.","D":"One figure can''t show growth."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'medium', 0, 'mcq', 'While researching a topic, a student has taken the following notes:
• The kalimba is sometimes called a thumb piano.
• It has metal tines attached to a wooden board.
• Players pluck the tines with their thumbs.
• Instruments of this kind originated in Africa.', 'The student wants to describe how the kalimba is played. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Instruments like the kalimba originated in Africa."},{"id":"B","text":"A kalimba is played by plucking its metal tines with the thumbs."},{"id":"C","text":"The kalimba is sometimes called a thumb piano."},{"id":"D","text":"A kalimba has a wooden board."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Only this choice explains the playing technique.', '{"A":"This gives the instrument''s origin, not how it is played.","C":"A nickname doesn''t describe how it''s played.","D":"This describes construction, not playing."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'medium', 0, 'mcq', 'While researching a topic, a student has taken the following notes:
• Lin Hart''s novel Paper Moons was published in 1999.
• Hart''s novel Iron Bells was published in 2008.
• Both novels are set in small towns in Ohio.
• Iron Bells is twice as long as Paper Moons.', 'The student wants to emphasize a similarity between the two novels. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Iron Bells is twice as long as Paper Moons."},{"id":"B","text":"Paper Moons was published in 1999, and Iron Bells in 2008."},{"id":"C","text":"Paper Moons was published in 1999."},{"id":"D","text":"Lin Hart''s novels Paper Moons and Iron Bells are both set in small towns in Ohio."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Their shared setting is the similarity in the notes.', '{"A":"This emphasizes a difference.","B":"This emphasizes a difference.","C":"This describes one novel only."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'hard', 1, 'mcq', 'While researching a topic, a student has taken the following notes:
• Researchers compared two ways of teaching fractions for six weeks.
• Method A used visual models; Method B used memorized rules.
• Method A students scored 15 points higher on problem-solving.
• Scores on simple computation were similar for both groups.', 'The student wants to present the study''s results while noting where the two methods did not differ. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Students taught with visual models scored 15 points higher on problem-solving."},{"id":"B","text":"Researchers compared two methods for teaching fractions over six weeks."},{"id":"C","text":"Method A used visual models, while Method B used memorized rules."},{"id":"D","text":"Students taught with visual models outscored those who memorized rules by 15 points on problem-solving, though both groups did similarly on simple computation."}]'::jsonb, '{"choice":"D"}'::jsonb, 'This choice gives both the difference and the area of no difference.', '{"A":"This omits where the methods didn''t differ.","B":"This gives no results.","C":"This describes the methods, not the results."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'hard', 1, 'mcq', 'While researching a topic, a student has taken the following notes:
• The Varden Bridge was built in 1889.
• At the time, it was the longest steel bridge in the region.
• It was closed to cars in 1990.
• It reopened in 2012 as a walkway for pedestrians.', 'The student wants to emphasize how the bridge''s use has changed over time. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Once used by cars, the 1889 Varden Bridge reopened in 2012 as a pedestrian walkway."},{"id":"B","text":"When it was built in 1889, the Varden Bridge was the region''s longest steel bridge."},{"id":"C","text":"The Varden Bridge was closed to cars in 1990."},{"id":"D","text":"The Varden Bridge is made of steel."}]'::jsonb, '{"choice":"A"}'::jsonb, 'This choice contrasts the earlier use (cars) with the current use (pedestrians).', '{"B":"This is about its size, not its changing use.","C":"This gives only one change, without the new use.","D":"Material isn''t about use."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'hard', 1, 'mcq', 'While researching a topic, a student has taken the following notes:
• Ferns reproduce using tiny spores spread by wind.
• Most fern species need moist conditions to survive and reproduce.
• Resurrection ferns can lose most of their water and appear dead.
• After rain, resurrection ferns turn green again within hours.', 'The student wants to explain what makes resurrection ferns unusual among ferns. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"Ferns reproduce using spores spread by wind."},{"id":"B","text":"Resurrection ferns turn green after rain."},{"id":"C","text":"Most fern species need moist conditions."},{"id":"D","text":"Unlike most ferns, which need moist conditions, resurrection ferns can lose most of their water and then revive after rain."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Being unusual requires a contrast with typical ferns, and only this choice makes it.', '{"A":"This applies to ferns in general.","B":"This omits the contrast with other ferns.","C":"This describes typical ferns, not the unusual ones."}'::jsonb),
  ('rw.eoi.synthesis', 'rw.eoi.synthesis.notes', 'hard', 1, 'mcq', 'While researching a topic, a student has taken the following notes:
• A survey asked 1,000 adults about their news habits.
• 62% read news online daily.
• 18% read a print newspaper daily.
• Among adults over 65, 41% read a print newspaper daily.', 'The student wants to contrast the overall rate of daily print reading with the rate among older adults. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[{"id":"A","text":"62% of surveyed adults read news online daily."},{"id":"B","text":"41% of adults over 65 read a print newspaper daily."},{"id":"C","text":"A survey asked 1,000 adults about their news habits."},{"id":"D","text":"While only 18% of all surveyed adults read a print newspaper daily, 41% of those over 65 did."}]'::jsonb, '{"choice":"D"}'::jsonb, 'The goal requires both rates, set against each other.', '{"A":"This is about online reading.","B":"This gives only the older group''s rate.","C":"This gives no rates."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.addition', 'easy', -1, 'mcq', 'The Oakdale community garden provides fresh vegetables to dozens of local families each summer. ______ it offers free weekend classes on composting, seed saving, and growing food in small spaces.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"However,"},{"id":"B","text":"Instead,"},{"id":"C","text":"Additionally,"},{"id":"D","text":"Therefore,"}]'::jsonb, '{"choice":"C"}'::jsonb, 'The second sentence adds another service, so an addition transition fits.', '{"A":"The classes don''t contrast with the vegetables.","B":"The classes don''t replace the vegetables.","D":"The classes aren''t a result of the vegetables."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'easy', -1, 'mcq', 'Most species of cactus grow in hot deserts that receive very little rain. ______ a few species thrive in cold mountain regions where snow covers the ground for several months each year.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Similarly,"},{"id":"B","text":"In contrast,"},{"id":"C","text":"For example,"},{"id":"D","text":"As a result,"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Cold-climate cacti contrast with the usual desert species.', '{"A":"Cold mountains aren''t similar to hot deserts.","C":"These species are exceptions, not examples of desert cacti.","D":"Desert cacti don''t cause mountain cacti."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.cause', 'easy', -1, 'mcq', 'After many students asked for more time to study on weekends, the city library extended its Saturday and Sunday hours last spring. ______ the number of weekend visitors nearly doubled within two months.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Nevertheless,"},{"id":"B","text":"For instance,"},{"id":"C","text":"Similarly,"},{"id":"D","text":"As a result,"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The visitor increase is a consequence of the longer hours.', '{"A":"The increase isn''t in spite of the longer hours.","B":"The increase isn''t an example of the change.","C":"The increase follows from the change rather than resembling it."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.addition', 'easy', -1, 'mcq', 'Many foods now eaten around the world were first grown in the Americas. ______ tomatoes, potatoes, and corn were all cultivated there long before they reached Europe and Asia.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"For example,"},{"id":"B","text":"However,"},{"id":"C","text":"Consequently,"},{"id":"D","text":"Instead,"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Tomatoes, potatoes, and corn are examples of foods first grown in the Americas.', '{"B":"The foods illustrate rather than contrast with the claim.","C":"They are examples, not results.","D":"Nothing is being replaced."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.addition', 'easy', -1, 'mcq', 'To make paper by hand, workers first soak plant fibers in water until the fibers break down into a soft pulp. ______ they spread the pulp on a fine screen, press out the water, and let the sheet dry.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"In contrast,"},{"id":"B","text":"Nevertheless,"},{"id":"C","text":"For example,"},{"id":"D","text":"Next,"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The text describes steps in order, so a sequence transition fits.', '{"A":"The steps don''t contrast; they follow in order.","B":"Nothing is being conceded.","C":"Spreading the pulp is the next step, not an example of soaking."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'medium', 0, 'mcq', 'When it was first released, the film was dismissed by many critics as slow and confusing, and it drew small audiences. ______ it has since become a favorite of viewers, who praise its patient, careful storytelling.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Likewise,"},{"id":"B","text":"Therefore,"},{"id":"C","text":"Nevertheless,"},{"id":"D","text":"For instance,"}]'::jsonb, '{"choice":"C"}'::jsonb, 'The film became beloved despite early criticism.', '{"A":"Later praise isn''t similar to early dismissal.","B":"Popularity doesn''t follow from the dismissal.","D":"Later popularity isn''t an example of early dismissal."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.cause', 'medium', 0, 'mcq', 'During the unusually dry summer, the river''s water level dropped by more than two meters. ______ cargo ships carrying grain downstream had to reduce their loads to avoid running aground in shallow stretches.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Nonetheless,"},{"id":"B","text":"Consequently,"},{"id":"C","text":"Similarly,"},{"id":"D","text":"In other words,"}]'::jsonb, '{"choice":"B"}'::jsonb, 'The low water level caused ships to carry less.', '{"A":"Lighter loads follow from, not despite, the low water.","C":"This is a result, not a similar case.","D":"The second sentence doesn''t restate the first."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.addition', 'medium', 0, 'mcq', 'The new wing of the Fairhaven Museum was designed with sustainability in mind. ______ its roof collects rainwater for the surrounding gardens, and its walls are built from recycled timber.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Nevertheless,"},{"id":"B","text":"Specifically,"},{"id":"C","text":"Instead,"},{"id":"D","text":"Meanwhile,"}]'::jsonb, '{"choice":"B"}'::jsonb, 'The second sentence gives specific features showing sustainable design.', '{"A":"The details support the claim; they don''t concede anything.","C":"Nothing is being replaced.","D":"These are details of the design, not simultaneous events."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'medium', 0, 'mcq', 'The bridge''s slender design was widely praised for its elegance. ______ engineers worried that its narrow supports might not withstand strong winds, and they added hidden steel cables during construction.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Therefore,"},{"id":"B","text":"For example,"},{"id":"C","text":"Still,"},{"id":"D","text":"Likewise,"}]'::jsonb, '{"choice":"C"}'::jsonb, '"Still" introduces a concern that stands despite the praise.', '{"A":"The worry isn''t a result of the praise.","B":"The worry isn''t an example of praise.","D":"The worry isn''t similar to the praise."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'medium', 0, 'mcq', 'Scientists expected the newly discovered fish species to live in shallow coastal water, as its closest relatives do. ______ the fish was found only at depths of more than one kilometer.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Similarly,"},{"id":"B","text":"As a result,"},{"id":"C","text":"In addition,"},{"id":"D","text":"Instead,"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The deep-water discovery replaced the expected shallow habitat.', '{"A":"The finding is unlike the expectation.","B":"The finding doesn''t result from the expectation.","C":"The finding contradicts rather than adds."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'hard', 1, 'mcq', 'The author''s first novel sold only a few hundred copies in its first year. ______ it caught the attention of a well-known critic, whose enthusiastic review led to a second printing and a much larger readership.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Even so,"},{"id":"B","text":"Thus,"},{"id":"C","text":"Similarly,"},{"id":"D","text":"In other words,"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Despite weak early sales, the book reached a critic who changed its fortunes, which is a concession.', '{"B":"The critic''s attention isn''t a result of weak sales.","C":"The review isn''t like the weak sales.","D":"The second sentence doesn''t restate the first."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.addition', 'hard', 1, 'mcq', 'Octopuses are remarkably flexible animals. ______ an octopus with an arm span of more than a meter can squeeze through an opening only a few centimeters wide, since its body has no rigid skeleton.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Indeed,"},{"id":"B","text":"However,"},{"id":"C","text":"Instead,"},{"id":"D","text":"Meanwhile,"}]'::jsonb, '{"choice":"A"}'::jsonb, '"Indeed" introduces a striking example that reinforces the claim.', '{"B":"The example strengthens the claim rather than contrasting with it.","C":"Nothing is replaced.","D":"This is evidence for the claim, not something happening at the same time."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.cause', 'hard', 1, 'mcq', 'Engineers found that the city''s oldest water pipes were made of a material that corrodes easily and can leach into drinking water. ______ officials have begun replacing the pipes, starting in the neighborhoods where they are oldest.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Nonetheless,"},{"id":"B","text":"By contrast,"},{"id":"C","text":"For instance,"},{"id":"D","text":"Accordingly,"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The replacement program is a fitting response to the finding.', '{"A":"The replacement is a response to the problem, not in spite of it.","B":"Nothing contrasts.","C":"Replacing pipes isn''t an example of corrosion."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'hard', 1, 'mcq', 'Both species of finch on the island eat seeds. ______ one species cracks large, hard seeds with its thick beak, while the other picks out small, soft seeds with a much thinner beak.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Therefore,"},{"id":"B","text":"However,"},{"id":"C","text":"Likewise,"},{"id":"D","text":"For this reason,"}]'::jsonb, '{"choice":"B"}'::jsonb, 'After a shared trait, the text turns to how the species differ.', '{"A":"The difference doesn''t follow from their similarity.","C":"The second sentence shows differences, not more similarity.","D":"Eating seeds doesn''t cause the difference."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'hard', 1, 'mcq', 'In 1850, a traveler journeying between the two cities spent four days in a crowded stagecoach. ______ by 1870, a new railroad made the same trip possible in a single afternoon.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Similarly,"},{"id":"B","text":"By contrast,"},{"id":"C","text":"For instance,"},{"id":"D","text":"Thus,"}]'::jsonb, '{"choice":"B"}'::jsonb, 'The two travel times are being contrasted.', '{"A":"An afternoon is very different from four days.","C":"1870 isn''t an example of 1850.","D":"The railroad isn''t a result of the stagecoach."}'::jsonb),
  ('rw.eoi.transitions', 'rw.eoi.transitions.contrast', 'hard', 1, 'mcq', 'Some economists argue that raising the minimum wage reduces employment. ______ a study comparing neighboring counties on opposite sides of a state border found no difference in employment after one state raised its minimum wage.', 'Which choice completes the text with the most logical transition?', '[{"id":"A","text":"Therefore,"},{"id":"B","text":"Similarly,"},{"id":"C","text":"Yet"},{"id":"D","text":"Moreover,"}]'::jsonb, '{"choice":"C"}'::jsonb, 'The study''s result runs against the economists'' argument.', '{"A":"The finding doesn''t follow from the argument.","B":"The finding challenges the argument.","D":"The finding doesn''t add support."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'easy', -1, 'mcq', 'The town of Brenford once sent its fallen leaves to a landfill each autumn. In 2015, the town began collecting leaves separately and turning them into compost, which it now gives away to residents for their gardens. The program has cut the town''s landfill fees and become one of its most popular services.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Brenford''s leaf composting program saves money and is popular with residents."},{"id":"B","text":"Landfills charge high fees for accepting leaves."},{"id":"C","text":"Residents of Brenford prefer vegetable gardens to flower gardens."},{"id":"D","text":"Brenford stopped collecting leaves in 2015."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The text describes Brenford''s switch to composting leaves and its two results: lower landfill fees and a popular free service.', '{"B":"Landfill fees are a supporting detail, not the main idea.","C":"The text never compares types of gardens.","D":"Brenford changed how it handles leaves; it did not stop collecting them."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.detail', 'easy', -1, 'mcq', 'Pianist Tomas Reyna practices for four hours every morning, but he rarely plays complete pieces during that time. Instead, he repeats short passages slowly, sometimes a single measure dozens of times, until each movement of his hands feels automatic. Only in the evening does he play full works from start to finish.', 'According to the text, what does Reyna do during his morning practice?', '[{"id":"A","text":"He plays complete works from start to finish."},{"id":"B","text":"He repeats short passages slowly many times."},{"id":"C","text":"He teaches students for four hours."},{"id":"D","text":"He listens to recordings of other pianists."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The text states that in the morning he "repeats short passages slowly," sometimes a single measure dozens of times.', '{"A":"The text says he does this in the evening, not the morning.","C":"Teaching is never mentioned.","D":"Listening to recordings is never mentioned."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'easy', -1, 'mcq', 'Researchers studying a shrub that grows in a foggy coastal desert found that its leaves are covered in tiny grooves. Fog droplets collect in the grooves and run down to the base of the plant, where the roots absorb them. The shrub can survive for months without rain by relying on fog alone.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"The shrub survives long periods without rain by channeling fog water to its roots."},{"id":"B","text":"Fog is common in every desert."},{"id":"C","text":"The shrub''s roots grow deeper than those of other desert plants."},{"id":"D","text":"Researchers have not yet explained how the shrub survives."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The text explains the shrub''s grooved leaves, how they move fog water to the roots, and that this lets it survive without rain.', '{"B":"The text describes one foggy desert, not all deserts.","C":"Root depth is never compared.","D":"The text explains exactly how the shrub survives."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.detail', 'easy', -1, 'mcq', 'When the Halverson Library reopened after a renovation, its staff noticed that the new reading room, with its large windows and movable chairs, was full every afternoon. The old room, which had fixed desks and little daylight, had often sat empty. Librarians now plan to redesign two smaller study areas in the same style.', 'According to the text, why do the librarians plan to redesign two study areas?', '[{"id":"A","text":"The study areas were damaged during the renovation."},{"id":"B","text":"Visitors complained that the new reading room was too bright."},{"id":"C","text":"The new reading room''s design proved popular with visitors."},{"id":"D","text":"The old reading room had too many chairs."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The new room was full every afternoon, so the librarians plan to copy its style in two study areas.', '{"A":"The text mentions no damage.","B":"The text reports that the bright room was full, not that people complained.","D":"The old room''s problem was fixed desks and little light, not too many chairs."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'easy', -1, 'mcq', 'Before refrigerators were common, some households kept food cool in a zeer, a pair of clay pots with one set inside the other and wet sand packed between them. As water in the sand evaporates through the outer pot, it draws heat away from the inner pot. The simple device can keep vegetables fresh for days in hot, dry climates.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Clay pots are the best containers for storing sand."},{"id":"B","text":"A zeer uses evaporation to keep food cool without electricity."},{"id":"C","text":"Refrigerators were invented to replace zeers."},{"id":"D","text":"Vegetables spoil faster in dry climates than in humid ones."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The text describes what a zeer is, how evaporation cools it, and what it can do.', '{"A":"The pots hold sand only as part of the cooling method.","C":"The text does not explain why refrigerators were invented.","D":"The text does not compare spoilage across climates."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'medium', 0, 'mcq', 'For decades, historians assumed that medieval farmers in the region rarely traveled more than a few miles from home. But account books recently found in a village archive record farmers selling wool at markets more than eighty miles away, sometimes several times a year. These records suggest that rural life was far less isolated than once believed.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Medieval farmers earned most of their income from selling wool."},{"id":"B","text":"Village archives are the most reliable source of medieval history."},{"id":"C","text":"Historians have long known that farmers traveled to distant markets."},{"id":"D","text":"Newly found records suggest that medieval farmers in the region traveled much more than historians had assumed."}]'::jsonb, '{"choice":"D"}'::jsonb, 'The text contrasts an old assumption with new evidence and concludes that rural life was less isolated than believed.', '{"A":"The records show wool sales but not the share of farmers'' income.","B":"The text does not rank sources by reliability.","C":"The text says historians assumed the opposite."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'medium', 0, 'mcq', 'Architect Sun-Hee Park designs schools without long hallways. In her buildings, classrooms open onto shared central spaces where students from different grades gather between lessons. Park argues that hallways isolate students, while shared spaces encourage the informal conversations through which younger students learn from older ones.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Park believes classrooms should be larger than they usually are."},{"id":"B","text":"Park designs schools around shared spaces because she believes they help students learn from one another."},{"id":"C","text":"Hallways are the most expensive part of a school to build."},{"id":"D","text":"Students in Park''s schools spend less time in classrooms."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The text describes Park''s hallway-free design and her reason for it: shared spaces encourage students to learn from each other.', '{"A":"Classroom size is never discussed.","C":"Cost is never mentioned.","D":"The text does not say how much time students spend in classrooms."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.detail', 'medium', 0, 'mcq', 'Economist Rafael Ortiz studied why some small towns kept their downtown shops while others lost them. He found that towns whose shops survived usually had a single organization, often run by the shop owners themselves, that planned shared events and advertised the downtown as a whole rather than store by store.', 'According to the text, what did Ortiz find about towns whose downtown shops survived?', '[{"id":"A","text":"They had more shops than other towns."},{"id":"B","text":"They usually had one organization that promoted the downtown as a whole."},{"id":"C","text":"Their shop owners advertised only their own stores."},{"id":"D","text":"They had larger populations than other towns."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Ortiz found a shared organization that "advertised the downtown as a whole rather than store by store."', '{"A":"The number of shops is not discussed.","C":"This is the opposite of what Ortiz found.","D":"Population is never mentioned."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'medium', 0, 'mcq', 'Octopuses are known for changing color, but biologist Mara Ilic was surprised to find that one species also changes the texture of its skin. When resting among rocks, these octopuses raise tiny bumps that mimic the surface of nearby stones, making them nearly impossible to spot even when their color does not match perfectly.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Octopuses cannot change color while they are resting."},{"id":"B","text":"One octopus species camouflages itself by changing the texture of its skin as well as its color."},{"id":"C","text":"Ilic discovered that octopuses can change color."},{"id":"D","text":"Octopuses prefer rocky areas because they are easy to see there."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The text''s focus is Ilic''s finding that the species also changes skin texture to blend in with rocks.', '{"A":"The text never says resting octopuses cannot change color.","C":"The text presents color change as already well known.","D":"The octopuses use rocks to hide, not to be seen."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.detail', 'medium', 0, 'mcq', 'Novelist Grace Adeyemi drafts her books by hand in notebooks, then types them herself, revising heavily as she goes. She says that typing a handwritten page forces her to reconsider every sentence, because she cannot simply copy text; she must decide again whether each line deserves to stay.', 'According to the text, why does Adeyemi type her handwritten drafts herself?', '[{"id":"A","text":"She dislikes the handwriting of her assistants."},{"id":"B","text":"Typing her drafts makes her reconsider each sentence."},{"id":"C","text":"Typing is faster than writing by hand."},{"id":"D","text":"Her publisher requires typed manuscripts."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Adeyemi says typing "forces her to reconsider every sentence."', '{"A":"Assistants are never mentioned.","C":"Speed is not her reason.","D":"Publisher requirements are never mentioned."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'medium', 0, 'mcq', 'Elena had walked past the bakery every morning for a year without going in. Today, the smell of cinnamon stopped her at the door. She stood there long enough for the baker to look up and wave, and she found, to her own surprise, that she was already reaching for the handle.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Elena unexpectedly decides to enter a bakery she has passed many times."},{"id":"B","text":"Elena dislikes the smell of cinnamon."},{"id":"C","text":"The baker asks Elena to work at the bakery."},{"id":"D","text":"Elena visits the bakery every morning."}]'::jsonb, '{"choice":"A"}'::jsonb, 'After a year of walking past, Elena is surprised to find herself reaching for the bakery''s door.', '{"B":"The smell draws her in, so she does not dislike it.","C":"The baker only waves.","D":"She passes the bakery every morning but has never gone in."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'medium', 0, 'mcq', 'When a small software company tried a four-day workweek, its managers expected the number of finished projects to drop. Instead, the share of projects finished on time rose slightly over six months, and fewer employees left the company. The managers caution, however, that the trial involved only one company and may not apply elsewhere.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Every company should adopt a four-day workweek."},{"id":"B","text":"A company''s four-day-week trial went better than expected, though its results may not apply to other companies."},{"id":"C","text":"The company finished fewer projects during the trial."},{"id":"D","text":"Employees left the company because of the trial."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The text reports better-than-expected results and the managers'' caution that one company''s trial may not generalize.', '{"A":"The managers specifically warn against generalizing.","C":"On-time projects rose slightly.","D":"Fewer employees left."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'hard', 1, 'mcq', 'Some critics dismiss detective novels as formula: a crime, a clever investigator, a solution. Literary scholar Ines Varga argues that this view misses what readers value. The pleasure of the genre, she contends, lies less in the solution than in the investigator''s way of noticing, the trained attention that turns an ordinary room into a field of clues, so that readers come away seeing their own surroundings differently.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Varga argues that detective novels are superior to other genres."},{"id":"B","text":"Varga argues that detective novels appeal mainly through the way they model careful observation."},{"id":"C","text":"Critics argue that detective novels have unpredictable solutions."},{"id":"D","text":"Varga claims that readers dislike the solutions in detective novels."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Varga''s central claim is that the genre''s pleasure comes from the investigator''s way of noticing, which changes how readers see.', '{"A":"Varga does not compare genres.","C":"The critics call the genre formulaic, not unpredictable.","D":"She says the solution matters less, not that readers dislike it."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'hard', 1, 'mcq', 'Ecologists long treated dead trees in forests as waste, and some forest managers removed them to reduce fire risk. Recent surveys, however, have found that standing dead trees shelter many nesting birds and that fallen logs hold moisture that seedlings depend on in dry summers. These findings have led some managers to leave a portion of dead wood in place, balancing fire concerns against the habitat it provides.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Dead trees increase fire risk more than living trees do."},{"id":"B","text":"Forest managers should never remove dead trees."},{"id":"C","text":"Evidence of dead trees'' ecological value has led some managers to stop removing all of them."},{"id":"D","text":"Seedlings grow best in forests with no fallen logs."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The text moves from the old view, to new evidence of habitat value, to managers'' changed practice.', '{"A":"The text does not compare fire risk from dead and living trees.","B":"Managers now leave a portion in place, balancing fire concerns; the text does not say never remove them.","D":"Fallen logs help seedlings in dry summers."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.detail', 'hard', 1, 'mcq', 'Music historian Kofi Mensah studied hundreds of handwritten band parts used by a touring brass ensemble in the early 1900s. Pencil markings in the margins, such as cuts, added repeats, and notes like "slower for hall," show that the ensemble altered pieces night to night depending on the venue. Mensah argues that the printed scores therefore record only a starting point, not how the music was actually heard.', 'According to the text, why does Mensah argue that the printed scores are only a starting point?', '[{"id":"A","text":"The printed scores were lost before the tour began."},{"id":"B","text":"Members of the ensemble could not read music."},{"id":"C","text":"Markings show that the ensemble changed the music for different performances."},{"id":"D","text":"The printed scores contained many printing errors."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The pencil markings show the music was altered for each venue, so the printed scores don''t capture what audiences heard.', '{"A":"The text does not say the scores were lost.","B":"The members wrote musical markings, so they could read music.","D":"Printing errors are never mentioned."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'hard', 1, 'mcq', 'Many people assume that bilingual children fall behind in vocabulary. Linguist Hana Sato notes that such children often know fewer words in each individual language than monolingual peers do, but when both languages are counted together, their total vocabulary is typically similar or larger. Sato argues that measuring only one language misrepresents what these children know.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Sato argues that bilingual children''s vocabulary is underestimated when only one language is measured."},{"id":"B","text":"Sato argues that bilingual children learn words more slowly than other children."},{"id":"C","text":"Bilingual children know more words in each language than monolingual children."},{"id":"D","text":"Sato believes vocabulary tests should be eliminated."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Sato''s main claim is that counting one language misrepresents bilingual children''s total vocabulary.', '{"B":"Sato''s point is that their total is similar or larger.","C":"The text says they often know fewer words in each language.","D":"Sato criticizes one way of measuring, not all tests."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'hard', 1, 'mcq', 'The letter lay unopened on the table for three days. Marcus moved it to make room for his coffee, then for a stack of bills, and once, absurdly, to dust beneath it. He knew the handwriting. He told himself he was simply busy, though the house had never been so clean.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Marcus does not recognize who sent the letter."},{"id":"B","text":"Marcus is too busy with bills to read his mail."},{"id":"C","text":"Marcus avoids opening a letter while telling himself that he is merely busy."},{"id":"D","text":"Marcus has lost the letter among his papers."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Marcus keeps handling the letter without opening it, and the spotless house shows that "busy" is an excuse.', '{"A":"He \"knew the handwriting.\"","B":"The clean house suggests his busyness is an excuse.","D":"He keeps moving the letter, so it is not lost."}'::jsonb),
  ('rw.ii.central', 'rw.ii.central.main', 'hard', 1, 'mcq', 'City planners often measure a park''s value by how many visitors it draws. Urban geographer Leila Haddad suggests a different measure: how long people stay. A plaza that thousands cross on their way elsewhere may be busy, she notes, but a small garden where neighbors linger for an hour may do more to build the everyday familiarity that makes a neighborhood feel safe.', 'Which choice best states the main idea of the text?', '[{"id":"A","text":"Haddad argues that busy plazas should be replaced with small gardens."},{"id":"B","text":"Haddad claims that busy plazas make neighborhoods less safe."},{"id":"C","text":"City planners usually measure parks by how long visitors stay."},{"id":"D","text":"Haddad proposes that how long people stay may reflect a park''s value better than how many people visit."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Haddad suggests measuring time spent rather than visitor counts, because lingering builds neighborhood familiarity.', '{"A":"She proposes a measure, not replacing plazas.","B":"She says gardens may do more, not that plazas harm safety.","C":"The text says planners usually count visitors."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'easy', -1, 'mcq', 'In the poem "Harbor at Dusk," the speaker describes a small fishing harbor at the end of a long working day. A student claims that the poem conveys a feeling of quiet rest after a day of hard effort.', 'Which quotation from the poem most effectively illustrates the student''s claim?', '[{"id":"A","text":"\"Gulls shriek and dive above the churning wake.\""},{"id":"B","text":"\"The engines roar before the break of day.\""},{"id":"C","text":"\"The nets hang folded, and the tired boats / lean softly on the slow and settling tide.\""},{"id":"D","text":"\"Ropes snap taut against the rising wind.\""}]'::jsonb, '{"choice":"C"}'::jsonb, 'Folded nets, "tired boats," and a "settling tide" together suggest calm after work.', '{"A":"Shrieking gulls and churning water suggest noise and motion, not rest.","B":"This describes the start of the day and loud engines.","D":"Snapping ropes and rising wind suggest tension, not rest."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.quantitative', 'easy', -1, 'mcq', '| Month | Tickets sold |
| January | 1,200 |
| February | 1,450 |
| March | 1,900 |

The manager of the Westfield Theater claims that ticket sales grew each month from January through March.', 'Which choice most effectively uses data from the table to support the claim?', '[{"id":"A","text":"Sales rose from 1,200 tickets in January to 1,450 in February and 1,900 in March."},{"id":"B","text":"The theater sold 1,450 tickets in February."},{"id":"C","text":"The theater sold fewer tickets in March than in January."},{"id":"D","text":"The theater sold 1,200 tickets in January."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Only this choice shows sales rising in each step: 1,200 → 1,450 → 1,900.', '{"B":"One month''s total can''t show growth from month to month.","C":"This is false; March sales were higher.","D":"One month''s total can''t show growth from month to month."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'easy', -1, 'mcq', 'Historian Ruth Abara argues that the Valley Courier, a newspaper published in the 1890s, strongly supported the construction of a new railroad through its county. She bases her argument on the paper''s surviving issues.', 'Which finding, if true, would most directly support Abara''s argument?', '[{"id":"A","text":"The Courier was founded in 1871."},{"id":"B","text":"The railroad was completed in 1896."},{"id":"C","text":"The Courier printed many editorials praising the railroad''s expected benefits."},{"id":"D","text":"Rival newspapers opposed the railroad."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Editorials praising the railroad would directly show the Courier''s support.', '{"A":"The founding date says nothing about the paper''s position.","B":"The completion date says nothing about the paper''s position.","D":"Other papers'' views don''t show the Courier''s view."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.quantitative', 'easy', -1, 'mcq', '| Year | Herons counted |
| 2019 | 42 |
| 2020 | 51 |
| 2021 | 63 |
| 2022 | 70 |

Volunteers at Lake Orin count herons each spring. A volunteer claims that the number of herons counted at the lake increased every year from 2019 to 2022.', 'Which choice most effectively uses data from the table to support the claim?', '[{"id":"A","text":"The count rose every year, from 42 in 2019 to 70 in 2022."},{"id":"B","text":"Volunteers counted 51 herons in 2020."},{"id":"C","text":"The count fell between 2021 and 2022."},{"id":"D","text":"More herons were counted in 2019 than in 2022."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The counts rise in each year shown: 42, 51, 63, 70.', '{"B":"One year''s count can''t show a yearly increase.","C":"This is false: the count rose from 63 to 70.","D":"This is false: 42 is less than 70."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'easy', -1, 'mcq', 'Researchers studying the amber leaf beetle, an insect that damages fruit trees, hypothesize that the beetle is strongly attracted to the color yellow. If so, farmers could use yellow traps to protect their orchards.', 'Which finding, if true, would most directly support the researchers'' hypothesis?', '[{"id":"A","text":"Traps painted yellow caught far more beetles than identical traps painted other colors."},{"id":"B","text":"The beetles are found in orchards in many countries."},{"id":"C","text":"Yellow flowers bloom earlier in spring than other flowers."},{"id":"D","text":"Traps of every color caught similar numbers of beetles."}]'::jsonb, '{"choice":"A"}'::jsonb, 'If yellow traps catch far more beetles than otherwise identical traps, the beetles are drawn to yellow.', '{"B":"Where the beetles live says nothing about color preference.","C":"This concerns flowers, not the beetles'' behavior.","D":"This would weaken the hypothesis."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.quantitative', 'easy', -1, 'mcq', '| Exhibit | Average daily visitors |
| Fossils | 340 |
| Space | 510 |
| Textiles | 190 |

A museum guide claims that the space exhibit was the most popular of the three exhibits shown.', 'Which choice most effectively uses data from the table to support the claim?', '[{"id":"A","text":"The fossil exhibit averaged 340 visitors a day."},{"id":"B","text":"The textile exhibit had the fewest visitors."},{"id":"C","text":"The fossil and textile exhibits together averaged 530 visitors a day."},{"id":"D","text":"The space exhibit averaged 510 visitors a day, more than the fossil (340) and textile (190) exhibits."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Only this choice compares the space exhibit''s figure with both of the others.', '{"A":"This gives one exhibit''s figure without comparing it to the space exhibit.","B":"This is true but doesn''t show that the space exhibit was most popular.","C":"Combining two exhibits doesn''t compare each one to the space exhibit."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'easy', -1, 'mcq', 'In a short story, the narrator, a young violinist, waits backstage before her first solo performance. A student claims that the narrator feels nervous in the moments before she walks onstage.', 'Which quotation from the story most effectively illustrates the student''s claim?', '[{"id":"A","text":"\"The hall was painted a pale, cheerful blue.\""},{"id":"B","text":"\"My teacher had chosen the piece months earlier.\""},{"id":"C","text":"\"My hands would not stop shaking as I tuned the violin for the third time.\""},{"id":"D","text":"\"Afterward, we all went out for a late dinner.\""}]'::jsonb, '{"choice":"C"}'::jsonb, 'Shaking hands and retuning the violin again and again show nervousness.', '{"A":"The hall''s color doesn''t show how the narrator feels.","B":"This gives background, not a feeling.","D":"This happens after the performance."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.quantitative', 'medium', 0, 'mcq', '| Transportation | Share of respondents |
| Bus | 34% |
| Train | 22% |
| Bicycle | 9% |
| Car | 35% |

A city report claims that more survey respondents use public transit, meaning buses and trains combined, than use cars.', 'Which choice most effectively uses data from the table to support the claim?', '[{"id":"A","text":"Cars are used by 35% of respondents, more than buses alone (34%)."},{"id":"B","text":"Buses (34%) and trains (22%) together account for 56% of respondents, compared with 35% for cars."},{"id":"C","text":"Bicycles are used by 9% of respondents."},{"id":"D","text":"Trains are used by 22% of respondents, fewer than cars."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The claim is about buses and trains combined, and 34% + 22% = 56% is greater than 35%.', '{"A":"This compares cars with buses alone, which seems to undercut the claim.","C":"Bicycles are not part of the claim.","D":"This compares trains alone with cars and doesn''t combine transit."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'medium', 0, 'mcq', 'Algae blooms have become common in Lake Merin. Some scientists claim that the blooms are caused mainly by fertilizer washing into the lake from nearby farms, rather than by rising water temperatures.', 'Which finding, if true, would most directly weaken the scientists'' claim?', '[{"id":"A","text":"Farms near the lake have used fertilizer for decades."},{"id":"B","text":"Blooms are most common in the summer months."},{"id":"C","text":"Blooms were just as frequent in years when nearby farms used little fertilizer as in years when they used a lot."},{"id":"D","text":"The amount of fertilizer washing into the lake has increased in recent years."}]'::jsonb, '{"choice":"C"}'::jsonb, 'If blooms don''t change when fertilizer use changes, fertilizer is unlikely to be the main cause.', '{"A":"This is consistent with the claim.","B":"Summer has both more runoff and warmer water, so this doesn''t separate the causes.","D":"This, if anything, supports the claim."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.quantitative', 'medium', 0, 'mcq', '| Hours of sleep | Average reaction time (milliseconds) |
| 5 | 410 |
| 6 | 380 |
| 7 | 350 |
| 8 | 330 |

Researchers claim that participants who slept more the night before a test tended to react faster.', 'Which choice most effectively uses data from the table to support the claim?', '[{"id":"A","text":"Participants who slept 6 hours averaged 380 milliseconds."},{"id":"B","text":"Average reaction time fell from 410 milliseconds for 5 hours of sleep to 330 milliseconds for 8 hours."},{"id":"C","text":"Reaction times rose as hours of sleep increased."},{"id":"D","text":"Participants who slept 7 hours had an average reaction time of 350 milliseconds."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Lower reaction times mean faster reactions, and times fall steadily as sleep increases.', '{"A":"One data point can''t show a trend.","C":"This is false; reaction times fell.","D":"One data point can''t show a trend."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'medium', 0, 'mcq', 'Literary critic Omar Sayed claims that in the novel The Glass Orchard, the main character''s growing confidence is shown mainly through how she speaks to her employer over the course of a year.', 'Which quotation from the novel most effectively illustrates the critic''s claim?', '[{"id":"A","text":"\"The orchard stretched for miles beyond the house.\""},{"id":"B","text":"\"Her employer owned three farms in the valley.\""},{"id":"C","text":"\"She had always loved the smell of ripe apples.\""},{"id":"D","text":"\"At first she answered only ''Yes, sir''; by winter she was the one asking the questions.\""}]'::jsonb, '{"choice":"D"}'::jsonb, 'The shift from "Yes, sir" to asking questions shows her confidence growing in how she speaks to her employer.', '{"A":"This describes the setting, not her speech.","B":"This describes the employer''s property.","C":"This describes a preference, not growing confidence."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.quantitative', 'medium', 0, 'mcq', '| Month | Ashford rainfall (mm) | Bellvue rainfall (mm) |
| April | 80 | 65 |
| May | 95 | 70 |
| June | 60 | 55 |

A geography student claims that Ashford received more rain than Bellvue in every month shown.', 'Which choice most effectively uses data from the table to support the claim?', '[{"id":"A","text":"In each month, Ashford''s rainfall was higher: 80 vs. 65 mm in April, 95 vs. 70 in May, and 60 vs. 55 in June."},{"id":"B","text":"Ashford received 95 mm of rain in May."},{"id":"C","text":"Bellvue received less rain in June than in May."},{"id":"D","text":"Both cities received the least rain in June."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The claim is about every month, so the support must compare both cities in each month.', '{"B":"One month doesn''t show every month.","C":"This compares Bellvue with itself.","D":"This doesn''t compare the two cities."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.quantitative', 'hard', 1, 'mcq', '| Soil temperature | Species A germination | Species B germination |
| 10°C | 20% | 45% |
| 20°C | 65% | 50% |
| 30°C | 80% | 40% |

A botanist hypothesizes that warmer soil benefits the germination of species A more than it benefits species B.', 'Which choice most effectively uses data from the table to support the claim?', '[{"id":"A","text":"At 10°C, species B germinated at a higher rate than species A."},{"id":"B","text":"At 20°C, species A germinated at 65% and species B at 50%."},{"id":"C","text":"From 10°C to 30°C, species A''s germination rose from 20% to 80%, while species B''s fell from 45% to 40%."},{"id":"D","text":"Species B germinated at 40% at 30°C."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The hypothesis concerns how each species responds to warming, which requires comparing their changes from cool to warm soil.', '{"A":"This is one temperature and doesn''t show the effect of warming.","B":"This is one temperature and doesn''t show change.","D":"This gives one value for one species."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'hard', 1, 'mcq', 'After the city of Danvers added bike lanes to several commercial streets, some shop owners feared that losing parking spaces would hurt their sales. Economist Dana Whitford argues that the bike lanes did not reduce sales at nearby shops.', 'Which finding, if true, would most directly support Whitford''s argument?', '[{"id":"A","text":"Many shop owners opposed the bike lanes before construction."},{"id":"B","text":"Sales at shops on streets with new bike lanes changed by about the same amount as sales at similar shops on streets without them."},{"id":"C","text":"The number of cyclists using the lanes rose steadily after they opened."},{"id":"D","text":"Sales at shops on streets with bike lanes rose during the holiday season."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Comparing similar shops with and without bike lanes isolates the lanes'' effect. Similar changes suggest no harm.', '{"A":"Owners'' fears are not evidence about sales.","C":"Lane use doesn''t show what happened to sales.","D":"Without a comparison, a holiday rise could happen anywhere."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.quantitative', 'hard', 1, 'mcq', '| Age group | Read a print newspaper weekly |
| 18–29 | 12% |
| 30–49 | 21% |
| 50–64 | 38% |
| 65 and older | 55% |

A media researcher claims that weekly print newspaper reading becomes more common with each older age group.', 'Which choice most effectively uses data from the table to support the claim?', '[{"id":"A","text":"38% of adults aged 50–64 read a print newspaper weekly."},{"id":"B","text":"The share rises with each age group, from 12% of adults aged 18–29 to 55% of those 65 and older."},{"id":"C","text":"Fewer than a quarter of adults aged 30–49 read a print newspaper weekly."},{"id":"D","text":"Adults aged 18–29 read print newspapers more often than adults aged 30–49."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The claim is about a steady rise across all groups, and 12%, 21%, 38%, and 55% show exactly that.', '{"A":"One group can''t show a pattern across groups.","C":"This is true but doesn''t compare the groups.","D":"This is false: 12% is less than 21%."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'hard', 1, 'mcq', 'A species of small wasp lays its eggs inside caterpillars. Biologists hypothesize that the wasps locate host caterpillars mainly by scent rather than by sight.', 'Which finding, if true, would most directly support the biologists'' hypothesis?', '[{"id":"A","text":"Wasps found caterpillars hidden inside sealed, opaque mesh bags as quickly as they found caterpillars left in plain view."},{"id":"B","text":"Wasps found visible caterpillars faster than hidden ones."},{"id":"C","text":"The wasps are active only during daylight hours."},{"id":"D","text":"Caterpillars release a distinctive scent when they chew leaves."}]'::jsonb, '{"choice":"A"}'::jsonb, 'If hiding the caterpillars from view doesn''t slow the wasps, they must be using something other than sight, such as scent.', '{"B":"This suggests sight matters, which weakens the hypothesis.","C":"Daytime activity, if anything, hints that sight matters.","D":"This shows a scent exists, not that wasps use it."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.quantitative', 'hard', 1, 'mcq', '| City | Average commute 2010 (minutes) | Average commute 2020 (minutes) |
| Arden | 24 | 27 |
| Bellmont | 31 | 29 |
| Cresby | 19 | 26 |

An urban planner claims that, of the three cities, Cresby saw the largest increase in average commute time between 2010 and 2020.', 'Which choice most effectively uses data from the table to support the claim?', '[{"id":"A","text":"Bellmont had the longest average commute in both years."},{"id":"B","text":"Cresby''s average commute rose by 7 minutes, more than Arden''s 3-minute rise, while Bellmont''s fell."},{"id":"C","text":"Arden''s average commute rose from 24 to 27 minutes."},{"id":"D","text":"Cresby had the shortest average commute in 2010."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The claim compares increases, and Cresby rose 7 minutes, Arden 3, and Bellmont fell 2.', '{"A":"This is true but concerns length, not change.","C":"This describes only Arden.","D":"This is true but concerns one year, not change."}'::jsonb),
  ('rw.ii.evidence', 'rw.ii.evidence.textual', 'hard', 1, 'mcq', 'In the 1880s, the city of Haverly built several large public bathhouses. Historian Paulo Brandt claims that the city built the bathhouses mainly to improve public health rather than to provide places of leisure.', 'Which finding, if true, would most directly support Brandt''s claim?', '[{"id":"A","text":"City council records describe the bathhouses'' purpose as reducing the spread of disease in crowded districts."},{"id":"B","text":"The bathhouses included gardens and a café."},{"id":"C","text":"Many residents visited the bathhouses on weekends."},{"id":"D","text":"The bathhouses were among the largest buildings in the city."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Records stating the bathhouses'' purpose as disease prevention directly support a public-health motive.', '{"B":"Leisure features, if anything, weaken the claim.","C":"Weekend visits suggest leisure use and don''t show the city''s purpose.","D":"Size doesn''t indicate purpose."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'easy', -1, 'mcq', 'Bees visit flowers to collect nectar and pollen. Researchers placed identical feeders filled with sugar water in a garden, painting some blue and some white. Over a week, bees visited the blue feeders far more often than the white ones. This result suggests that the bees ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"cannot see the color white."},{"id":"B","text":"may be more attracted to blue than to white."},{"id":"C","text":"prefer sugar water to nectar."},{"id":"D","text":"visit only blue flowers in the wild."}]'::jsonb, '{"choice":"B"}'::jsonb, 'The feeders differed only in color, so the difference in visits points to a preference for blue.', '{"A":"Bees did visit white feeders, just less often.","C":"Sugar water and nectar were never compared.","D":"The study involved feeders, not wild flowers, and says nothing about \"only.\""}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'easy', -1, 'mcq', 'A bakery noticed that its bread sold out by noon on days when it opened at 6 a.m., but bread was often left over on days when it opened at 8 a.m. Because many customers buy bread on their way to work, the owner concluded that ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"customers prefer bread baked in the afternoon."},{"id":"B","text":"the bakery should close at noon every day."},{"id":"C","text":"customers never buy bread on weekends."},{"id":"D","text":"opening earlier lets the bakery reach more of its morning customers."}]'::jsonb, '{"choice":"D"}'::jsonb, 'If customers buy bread on the way to work, opening before they commute captures those sales.', '{"A":"Afternoon baking is never discussed.","B":"Selling out by noon doesn''t mean the bakery should close then.","C":"Weekends are never mentioned."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'easy', -1, 'mcq', 'Glaciers form when snow builds up over many years and is compressed into ice. In a mountain range where yearly snowfall has declined for decades while summer temperatures have risen, scientists would most likely expect the glaciers to ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"grow larger each year."},{"id":"B","text":"shrink over time."},{"id":"C","text":"stay exactly the same size."},{"id":"D","text":"form more quickly than before."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Less snow adds less ice and warmer summers melt more, so the glaciers should shrink.', '{"A":"Less snow and more melting both work against growth.","C":"Both trends change the ice.","D":"Less snowfall means less new ice."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'easy', -1, 'mcq', 'In a study, students who took handwritten notes during a lecture later remembered more of it than students who typed notes, even though the typists recorded more words. The researchers suggested that because handwriting is slower, students must decide what to write, which requires them to ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"copy the lecture word for word."},{"id":"B","text":"ignore most of the lecture."},{"id":"C","text":"type faster than they can write."},{"id":"D","text":"think about and summarize the material as they listen."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Choosing what to write means processing and condensing ideas, which may explain the better memory.', '{"A":"Slow handwriting makes word-for-word copying impossible.","B":"They remembered more, so they did not ignore it.","C":"This doesn''t follow from handwriting being slow."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'easy', -1, 'mcq', 'A city added a lane for buses only on its busiest street. Before the lane opened, buses on that route took an average of 40 minutes; afterward, the same trip took 28 minutes, while traffic on nearby streets did not change. These results suggest that the bus lane ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"slowed traffic on nearby streets."},{"id":"B","text":"shortened bus travel times on that route."},{"id":"C","text":"made the buses slower."},{"id":"D","text":"had no effect on bus travel."}]'::jsonb, '{"choice":"B"}'::jsonb, 'Trips got 12 minutes shorter with no change elsewhere, which points to the bus lane.', '{"A":"Traffic on nearby streets did not change.","C":"Travel time fell from 40 to 28 minutes.","D":"Travel times clearly changed."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'easy', -1, 'mcq', 'The seeds of many plants can remain dormant in soil for years, sprouting only when conditions become favorable. After a fire cleared the tall trees shading a hillside, botanists found many seedlings of a species that had not been seen there for decades. The botanists concluded that seeds of the species had most likely ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"been created by the heat of the fire."},{"id":"B","text":"never been present on the hillside before."},{"id":"C","text":"grown only in deep shade."},{"id":"D","text":"been lying dormant in the soil until sunlight reached it."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Dormant seeds can wait for favorable conditions, and removing the shade provided them.', '{"A":"Fire doesn''t create seeds.","B":"The species had grown there before, decades earlier.","C":"The seedlings appeared only after the shade was removed."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'easy', -1, 'mcq', 'Two identical apartment buildings were built side by side, one painted white and the other dark gray. During a summer heat wave, residents of the gray building used their air conditioners much more often than residents of the white building. A likely explanation is that the gray building ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"absorbed more heat from the sun than the white building did."},{"id":"B","text":"had fewer residents than the white building."},{"id":"C","text":"stayed cooler than the white building."},{"id":"D","text":"had no air conditioners."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The buildings differ only in color, and dark surfaces absorb more sunlight, so the gray building likely got hotter.', '{"B":"The buildings are identical except for color.","C":"More air-conditioner use suggests it was hotter.","D":"Its residents used air conditioners."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'medium', 0, 'mcq', 'Linguists have observed that words for everyday objects tend to be short, while words for rare things tend to be longer. One explanation is that speakers shorten words they use often to save effort. If this explanation is correct, a newly invented device that becomes common in daily life would most likely ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"come to be called by a shorter name over time."},{"id":"B","text":"keep its original long name permanently."},{"id":"C","text":"be named after its inventor."},{"id":"D","text":"be described using several separate words."}]'::jsonb, '{"choice":"A"}'::jsonb, 'If frequent use leads speakers to shorten words, a device that becomes common should get a shorter name.', '{"B":"The explanation predicts that frequent words get shorter.","C":"The explanation says nothing about inventors.","D":"This would make the name longer, not shorter."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'medium', 0, 'mcq', 'Farmers who planted strips of wildflowers along the edges of their fields found fewer crop pests than farmers who did not. The wildflowers support insects that prey on pests, and these predators depend on flowers for food when pests are scarce. Removing the wildflower strips would therefore most likely ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"reduce the number of predatory insects and allow pests to increase."},{"id":"B","text":"increase the number of predatory insects."},{"id":"C","text":"have no effect on pest numbers."},{"id":"D","text":"eliminate crop pests entirely."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Without flowers, predators lose a food source. Fewer predators means more pests.', '{"B":"The predators depend on the flowers.","C":"The flowers support the predators that control pests.","D":"Fewer predators would mean more pests, not none."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'medium', 0, 'mcq', 'The ancient city of Toreth was known for its pottery. Archaeologists have found Toreth-style pots at sites hundreds of miles away, and chemical tests show that the clay in those pots matches deposits found only near Toreth itself. This evidence suggests that the pots ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"were made at the distant sites by potters copying Toreth''s style."},{"id":"B","text":"were never used for trade."},{"id":"C","text":"were made in Toreth and carried to the distant sites."},{"id":"D","text":"were made from clay found near the distant sites."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Clay found only near Toreth means the pots were made there, then moved.', '{"A":"The clay comes only from near Toreth.","B":"Carrying pots hundreds of miles points to trade.","D":"The tests show the clay came from near Toreth."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'medium', 0, 'mcq', 'Most owls hunt at night, but one grassland owl species often hunts during the day. Researchers found that in regions where this owl hunts by day, its main prey, a species of vole, is also most active during daylight. The researchers concluded that the owl''s hunting schedule is likely shaped by ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"the brightness of the moon."},{"id":"B","text":"competition with other owls at night."},{"id":"C","text":"when its prey is most active."},{"id":"D","text":"the temperature of the grasslands."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The owl hunts by day where its prey is active by day, which suggests the prey drives its schedule.', '{"A":"The finding concerns daytime prey activity, not moonlight.","B":"Competition was not studied.","D":"Temperature was not studied."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'medium', 0, 'mcq', 'A publisher released one novel with two different covers: one with a photograph of a city, the other with an abstract painting. In bookstores that displayed both, the photograph version sold twice as many copies. Online, where buyers mostly saw small thumbnail images, the two versions sold equally well. These results suggest that the photograph cover''s advantage ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"came from a lower price."},{"id":"B","text":"existed only for online buyers."},{"id":"C","text":"depended on buyers seeing the cover at full size."},{"id":"D","text":"came from the novel''s content."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The advantage appeared in stores, where covers are seen full size, and vanished online, where they''re tiny.', '{"A":"Price is never mentioned.","B":"Online, the versions sold equally.","D":"Both versions had the same content."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'medium', 0, 'mcq', 'Spiders of one species weave a thick zigzag band of silk into the center of their webs. Some scientists proposed that the band warns birds, which might otherwise fly through and destroy the web. In a test, webs with the band were damaged by birds far less often than webs from which the band had been removed. The test therefore supports the idea that the band ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"helps protect the web from birds."},{"id":"B","text":"attracts birds to the web."},{"id":"C","text":"helps the web catch more insects."},{"id":"D","text":"serves no purpose."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Webs with the band suffered less bird damage, which supports its role as a warning.', '{"B":"Webs with the band were damaged less, not more.","C":"Insect capture was not tested.","D":"Removing the band changed the damage rate."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'medium', 0, 'mcq', 'Some coastal towns that rely on tourism see their population triple each summer. In one such town, the water treatment plant was built decades ago to serve only the year-round population. Town officials have warned that during the summer months, the plant may ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"produce far more water than the town needs."},{"id":"B","text":"close because too few people use it."},{"id":"C","text":"serve only the tourists."},{"id":"D","text":"struggle to handle the much larger demand."}]'::jsonb, '{"choice":"D"}'::jsonb, 'A plant sized for the year-round population would be strained when the population triples.', '{"A":"Summer demand rises; the plant was built for fewer people.","B":"Summer brings more users, not fewer.","C":"Nothing suggests it would stop serving residents."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'hard', 1, 'mcq', 'Historians have long debated why a medieval river town declined. Some blame a war that reached the region in 1410. Tax records, however, show that the town''s income fell steadily for thirty years before the war began, during the same decades in which the river beside it gradually filled with silt and became too shallow for cargo ships. These records suggest that ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"the town''s decline likely began before the war and may have been driven by the river''s silting."},{"id":"B","text":"the war was the only cause of the town''s decline."},{"id":"C","text":"the town''s income rose until the war began."},{"id":"D","text":"cargo ships avoided the town because of its high taxes."}]'::jsonb, '{"choice":"A"}'::jsonb, 'The decline predates the war and coincides with the river becoming too shallow for trade.', '{"B":"Income was falling decades before the war.","C":"The records show income falling, not rising.","D":"Taxes are the evidence here, not the cause; silt blocked the ships."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'hard', 1, 'mcq', 'In experiments, people asked to predict how happy they would be a year after a major life event, such as moving to a new city, usually expected strong and lasting effects. When researchers checked in a year later, most people''s happiness had returned close to its earlier level. This pattern suggests that people tend to ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"underestimate how much events will affect them."},{"id":"B","text":"become permanently happier after moving."},{"id":"C","text":"overestimate how long the emotional effects of events will last."},{"id":"D","text":"be unable to predict anything about their futures."}]'::jsonb, '{"choice":"C"}'::jsonb, 'People expected lasting effects, but happiness returned to its baseline, so they overestimated how long the effects would last.', '{"A":"They predicted strong, lasting effects that did not last.","B":"Happiness returned to earlier levels.","D":"This overgeneralizes; the finding concerns emotional duration."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'hard', 1, 'mcq', 'Painter Lucia Ferro mixed her own pigments, and her notebooks list the ingredients of every color she used. When conservators analyzed a painting long credited to Ferro, they found a blue pigment that was not manufactured until twenty years after her death. Unless the painting was later retouched, this finding indicates that ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"Ferro invented the blue pigment herself."},{"id":"B","text":"Ferro''s notebooks are inaccurate about every color."},{"id":"C","text":"the painting was finished before Ferro''s death."},{"id":"D","text":"the painting was probably not painted by Ferro, at least not entirely."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Ferro could not have used a pigment that didn''t yet exist, so someone else painted at least part of the work.', '{"A":"The pigment didn''t exist until after her death.","B":"One pigment doesn''t discredit every notebook entry.","C":"A pigment made after her death means some paint was applied after she died."}'::jsonb),
  ('rw.ii.inferences', 'rw.ii.inferences.complete', 'hard', 1, 'mcq', 'A school district introduced a free breakfast program at half of its schools, chosen at random. After a year, attendance rose at the schools with the program but stayed flat at the others, while test scores rose slightly at both groups of schools. Based on these results, the program most likely ______', 'Which choice most logically completes the text?', '[{"id":"A","text":"improved attendance, but its effect on test scores is unclear."},{"id":"B","text":"caused test scores to rise."},{"id":"C","text":"reduced attendance."},{"id":"D","text":"had no measurable effect."}]'::jsonb, '{"choice":"A"}'::jsonb, 'Random assignment links the attendance gain to the program. Scores rose everywhere, so the program''s effect on scores can''t be separated out.', '{"B":"Scores rose at schools without the program too.","C":"Attendance rose at the program schools.","D":"Attendance rose only where the program ran."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.sentence', 'easy', -1, 'mcq', 'The town''s annual kite festival takes place every April on the beach near the old lighthouse. Hundreds of visitors attend each ______ many of them bring homemade kites decorated with bright paper and ribbon.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"year,"},{"id":"B","text":"year"},{"id":"C","text":"year, and,"},{"id":"D","text":"year;"}]'::jsonb, '{"choice":"D"}'::jsonb, 'A semicolon correctly joins the two independent clauses.', '{"A":"A comma alone between two independent clauses is a comma splice.","B":"With no punctuation, the clauses run together.","C":"The comma after \"and\" is incorrect."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.none', 'easy', -1, 'mcq', 'Researchers studying the migration of monarch butterflies have attached tiny, lightweight ______ to the wings of hundreds of the insects so that their routes can be tracked across North America.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"tags,"},{"id":"B","text":"tags"},{"id":"C","text":"tags;"},{"id":"D","text":"tags:"}]'::jsonb, '{"choice":"B"}'::jsonb, '"Tags" is the object of "have attached," and no punctuation belongs between it and "to the wings."', '{"A":"A comma would separate the verb''s object from the rest of the phrase.","C":"A semicolon needs an independent clause on each side.","D":"Nothing that follows explains or lists, so a colon doesn''t fit."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.semicolon_colon', 'easy', -1, 'mcq', 'The architect sketched dozens of designs for the new library before settling on a final ______ the building would have a curved glass front facing the town square.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"plan:"},{"id":"B","text":"plan,"},{"id":"C","text":"plan"},{"id":"D","text":"plan, which"}]'::jsonb, '{"choice":"A"}'::jsonb, 'A colon introduces an independent clause that explains what the final plan was.', '{"B":"A comma alone creates a comma splice.","C":"With no punctuation, the clauses run together.","D":"\"Which\" creates a clause that doesn''t fit grammatically with what follows."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.supplements', 'easy', -1, 'mcq', 'The author''s most recent novel, ______ was published last fall and quickly became a bestseller in several countries, follows three sisters who run their family''s struggling farm.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"which,"},{"id":"B","text":"it"},{"id":"C","text":"which"},{"id":"D","text":"and it"}]'::jsonb, '{"choice":"C"}'::jsonb, '"Which was published…" is a supplementary clause set off by commas, and "follows" is the main verb.', '{"A":"No comma belongs between \"which\" and its verb.","B":"\"It\" creates a comma splice inside the sentence.","D":"\"And it\" leaves the main verb \"follows\" without a proper subject."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.sentence', 'easy', -1, 'mcq', 'Early bicycles had no gears, so riders had to pedal very hard to climb even gentle ______ later designs added gears that made hills far easier to manage.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"slopes,"},{"id":"B","text":"slopes"},{"id":"C","text":"slopes;"},{"id":"D","text":"slopes, and,"}]'::jsonb, '{"choice":"C"}'::jsonb, 'A semicolon correctly separates the two independent clauses.', '{"A":"A comma alone between independent clauses is a comma splice.","B":"With no punctuation, the clauses run together.","D":"The comma after \"and\" is incorrect."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.semicolon_colon', 'medium', 0, 'mcq', 'Opening this weekend at the city museum after two years of planning, the newest exhibit features artifacts from three ancient ______ Egypt, Mesopotamia, and the Indus Valley.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"civilizations;"},{"id":"B","text":"civilizations,"},{"id":"C","text":"civilizations."},{"id":"D","text":"civilizations:"}]'::jsonb, '{"choice":"D"}'::jsonb, 'A colon after a complete clause introduces the list of the three civilizations.', '{"A":"A semicolon can''t introduce a list.","B":"A comma makes it unclear whether the list names the civilizations.","C":"A period leaves the list as a fragment."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.supplements', 'medium', 0, 'mcq', 'Marine biologist Lena Okoro—who has studied coral reefs in the Pacific for more than two ______ believes that some reefs may adapt to warmer water faster than scientists once thought.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"decades—"},{"id":"B","text":"decades,"},{"id":"C","text":"decades"},{"id":"D","text":"decades;"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The dash pair sets off the supplementary clause about Okoro''s research.', '{"B":"An interruption that opens with a dash must close with a dash.","C":"Without closing punctuation, the interruption runs into the main clause.","D":"A semicolon would separate the subject from its verb \"believes.\""}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.sentence', 'medium', 0, 'mcq', 'Volunteers removed more than two tons of trash from the river during the spring ______ the city plans to hold a second cleanup in the fall, when water levels are lower.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"cleanup, and"},{"id":"B","text":"cleanup,"},{"id":"C","text":"cleanup"},{"id":"D","text":"cleanup and,"}]'::jsonb, '{"choice":"A"}'::jsonb, 'A comma plus "and" correctly joins the two independent clauses.', '{"B":"A comma alone between independent clauses is a comma splice.","C":"With no punctuation, the clauses run together.","D":"The comma belongs before \"and,\" not after it."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.none', 'medium', 0, 'mcq', 'The data collected by the weather balloons launched from the coastal ______ helped forecasters predict the storm''s path more accurately than ever before, giving residents extra time to prepare.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"station,"},{"id":"B","text":"station;"},{"id":"C","text":"station"},{"id":"D","text":"station—"}]'::jsonb, '{"choice":"C"}'::jsonb, 'The subject ("The data… station") must flow directly into the verb "helped," with no punctuation.', '{"A":"A comma would separate the long subject from its verb \"helped.\"","B":"A semicolon would separate the subject from its verb.","D":"A dash would separate the subject from its verb."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.semicolon_colon', 'medium', 0, 'mcq', 'The engineering team''s first prototype, built mostly from spare parts, failed during testing in ______ the second, built with a lighter frame, completed every trial without a single problem.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"March, however,"},{"id":"B","text":"March, however;"},{"id":"C","text":"March; however,"},{"id":"D","text":"March however,"}]'::jsonb, '{"choice":"C"}'::jsonb, 'A semicolon ends the first clause, and "however," opens the second.', '{"A":"A comma before \"however\" creates a comma splice.","B":"The semicolon must come before \"however,\" since \"however\" begins the second clause.","D":"Without punctuation before \"however,\" the clauses run together."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.supplements', 'medium', 0, 'mcq', 'The festival''s headline performer, ______ a jazz pianist known for blending traditional and modern styles, will close the event on Saturday night with a two-hour concert.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"Ana Ruiz"},{"id":"B","text":"Ana Ruiz;"},{"id":"C","text":"Ana Ruiz—"},{"id":"D","text":"Ana Ruiz,"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The name and the description are each set off by commas as appositives describing "performer."', '{"A":"Without a comma, the name runs into the description.","B":"A semicolon can''t separate these phrases.","C":"A dash can''t pair with the comma that opened the phrase."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.semicolon_colon', 'medium', 0, 'mcq', 'To prepare for the two-week mountain expedition, each member of the team packed the same basic ______ a tent, a sleeping bag, a small stove, and enough food for ten days.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"supplies:"},{"id":"B","text":"supplies"},{"id":"C","text":"supplies;"},{"id":"D","text":"supplies,"}]'::jsonb, '{"choice":"A"}'::jsonb, 'A colon after the complete clause introduces the list of supplies.', '{"B":"Without punctuation, the list runs into the clause awkwardly.","C":"A semicolon can''t introduce a list.","D":"A comma makes it unclear that the list names the supplies."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.sentence', 'hard', 1, 'mcq', 'In the 1920s, the city''s subway system expanded rapidly, adding new lines to neighborhoods that had previously been reachable only by ______ by 1930, nearly every resident lived within a ten-minute walk of a station.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"streetcar,"},{"id":"B","text":"streetcar;"},{"id":"C","text":"streetcar"},{"id":"D","text":"streetcar, and,"}]'::jsonb, '{"choice":"B"}'::jsonb, 'The long first clause ends at "streetcar," and a semicolon joins it to the next independent clause.', '{"A":"A comma alone creates a comma splice.","C":"With no punctuation, the clauses run together.","D":"The comma after \"and\" is incorrect."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.semicolon_colon', 'hard', 1, 'mcq', 'After two years of data collection in schools across the state, the study''s conclusion was ______ students who slept at least eight hours performed better on memory tests than those who slept less.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"clear,"},{"id":"B","text":"clear;"},{"id":"C","text":"clear"},{"id":"D","text":"clear:"}]'::jsonb, '{"choice":"D"}'::jsonb, 'A colon introduces the clause that states what the clear conclusion was.', '{"A":"A comma alone creates a comma splice.","B":"A semicolon would suggest an unrelated clause, but what follows explains the conclusion.","C":"With no punctuation, the clauses run together."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.none', 'hard', 1, 'mcq', 'Over the past decade, scientists who study ancient ______ have found evidence that some early farmers kept dogs to help guard their herds of sheep and goats.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"DNA"},{"id":"B","text":"DNA,"},{"id":"C","text":"DNA;"},{"id":"D","text":"DNA—"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The clause "who study ancient DNA" identifies which scientists, so it takes no punctuation.', '{"B":"\"Who study ancient DNA\" is essential, so no comma should separate it from the verb.","C":"A semicolon would separate the subject from its verb.","D":"A dash would separate the subject from its verb."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.sentence', 'hard', 1, 'mcq', 'The painting, long thought to have been lost during the war, was discovered in an attic in ______ after experts confirmed its authenticity, it was donated to the national gallery.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"2019,"},{"id":"B","text":"2019"},{"id":"C","text":"2019, and,"},{"id":"D","text":"2019;"}]'::jsonb, '{"choice":"D"}'::jsonb, 'A semicolon separates two independent clauses; the second begins "after experts confirmed…".', '{"A":"A comma here creates a comma splice.","B":"With no punctuation, the clauses run together.","C":"The comma after \"and\" is incorrect."}'::jsonb),
  ('rw.sec.boundaries', 'rw.sec.boundaries.supplements', 'hard', 1, 'mcq', 'The chef''s signature dish—a soup made from roasted squash, fresh ginger, and ______ has been on the restaurant''s menu since it first opened its doors in 2004.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"coconut milk,"},{"id":"B","text":"coconut milk"},{"id":"C","text":"coconut milk;"},{"id":"D","text":"coconut milk—"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The dash pair sets off the description of the dish.', '{"A":"An interruption that opens with a dash must close with a dash.","B":"Without closing punctuation, the interruption runs into the main clause.","C":"A semicolon would separate the subject from its verb \"has been.\""}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.sv', 'easy', -1, 'mcq', 'The flowers in the garden behind the old schoolhouse ______ every spring, drawing visitors from across the county who come to see their bright colors.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"bloom"},{"id":"B","text":"blooms"},{"id":"C","text":"has bloomed"},{"id":"D","text":"is blooming"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The plural subject "flowers" takes the plural verb "bloom."', '{"B":"\"Blooms\" is singular, but the subject \"flowers\" is plural.","C":"\"Has bloomed\" is singular.","D":"\"Is blooming\" is singular."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.possessive', 'easy', -1, 'mcq', 'The ______ new playground opened last weekend, and families from across the city came to try its climbing wall and slides on the first warm day of the year.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"parks"},{"id":"B","text":"parks''"},{"id":"C","text":"parks''s"},{"id":"D","text":"park''s"}]'::jsonb, '{"choice":"D"}'::jsonb, 'One park owns the playground, so the singular possessive is "park''s."', '{"A":"\"Parks\" is plural, not possessive.","B":"\"Parks''\" is plural possessive, but there is one park.","C":"\"Parks''s\" is not a standard form."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.tense', 'easy', -1, 'mcq', 'Last summer, the research team ______ more than three hundred plant samples from the island''s forests, which the scientists are now analyzing in their laboratory.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"collects"},{"id":"B","text":"will collect"},{"id":"C","text":"is collecting"},{"id":"D","text":"collected"}]'::jsonb, '{"choice":"D"}'::jsonb, '"Last summer" marks a completed past action, so the verb is "collected."', '{"A":"\"Last summer\" calls for the past tense.","B":"\"Will collect\" is future.","C":"\"Is collecting\" is present."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.pronoun', 'easy', -1, 'mcq', 'The museum invited local artists to submit work for its annual community show, and more than two hundred of ______ responded with paintings, sculptures, and photographs.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"it"},{"id":"B","text":"them"},{"id":"C","text":"him"},{"id":"D","text":"its"}]'::jsonb, '{"choice":"B"}'::jsonb, 'The pronoun refers to the plural "artists," so "them" is correct.', '{"A":"\"It\" is singular, but \"artists\" is plural.","C":"\"Him\" is singular.","D":"\"Its\" is a singular possessive."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.sv', 'easy', -1, 'mcq', 'Each of the volunteers at the animal shelter ______ a short training course before working with the dogs and cats housed there, most of whom are waiting for new homes.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"complete"},{"id":"B","text":"are completing"},{"id":"C","text":"have completed"},{"id":"D","text":"completes"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The subject is "Each," which is singular, not "volunteers."', '{"A":"\"Complete\" is plural, but \"Each\" is singular.","B":"\"Are completing\" is plural.","C":"\"Have completed\" is plural."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.possessive', 'easy', -1, 'mcq', 'All of the ______ uniforms were replaced before the championship game, after the old ones had faded and frayed from many years of washing and wear.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"player''s"},{"id":"B","text":"players"},{"id":"C","text":"players''"},{"id":"D","text":"players''s"}]'::jsonb, '{"choice":"C"}'::jsonb, 'Many players own the uniforms, so the plural possessive is "players''."', '{"A":"\"Player''s\" is singular possessive, but the uniforms belong to many players.","B":"\"Players\" is not possessive.","D":"\"Players''s\" is not a standard form."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.tense', 'easy', -1, 'mcq', 'By the time the rescue boat arrived, the stranded hikers ______ on the small island for nearly two days, surviving on the snacks in their packs.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"wait"},{"id":"B","text":"will wait"},{"id":"C","text":"are waiting"},{"id":"D","text":"had waited"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The waiting happened before the boat arrived (a past event), so the past perfect "had waited" is needed.', '{"A":"\"Wait\" is present, but the events are past.","B":"\"Will wait\" is future.","C":"\"Are waiting\" is present."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.sv', 'medium', 0, 'mcq', 'Neither the coach nor the players ______ expecting the storm that suddenly forced the championship game to stop in the third quarter, sending fans running for cover.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"was"},{"id":"B","text":"were"},{"id":"C","text":"is"},{"id":"D","text":"has been"}]'::jsonb, '{"choice":"B"}'::jsonb, 'The verb agrees with "players," the subject closest to it, so it is plural: "were."', '{"A":"With \"neither… nor,\" the verb agrees with the nearer subject, the plural \"players.\"","C":"\"Is\" is singular and present.","D":"\"Has been\" is singular."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.pronoun', 'medium', 0, 'mcq', 'When the company released its annual report in March, ______ showed that sales had risen in every region except the north, where a new competitor had opened several stores.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"they"},{"id":"B","text":"we"},{"id":"C","text":"one"},{"id":"D","text":"it"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The pronoun refers to the singular "report," so "it" is correct.', '{"A":"\"They\" is plural, but \"report\" is singular.","B":"\"We\" doesn''t refer to the report.","C":"\"One\" doesn''t clearly refer to the report."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.tense', 'medium', 0, 'mcq', 'The novelist writes every morning before sunrise, long before the rest of the house is awake; she ______ that the quiet hours before dawn are when her best ideas arrive.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"said"},{"id":"B","text":"had said"},{"id":"C","text":"will have said"},{"id":"D","text":"says"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The text describes a current habit in the present tense, so "says" keeps the tense consistent.', '{"A":"The passage is in the present tense.","B":"\"Had said\" is past perfect.","C":"\"Will have said\" is future perfect."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.possessive', 'medium', 0, 'mcq', 'The research vessel spent three months at sea last year, and ______ crew collected water samples from more than forty locations across the southern ocean.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"its"},{"id":"B","text":"it''s"},{"id":"C","text":"their"},{"id":"D","text":"its''"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The crew belongs to the singular "vessel," so the possessive is "its."', '{"B":"\"It''s\" means \"it is.\"","C":"\"Their\" is plural, but \"vessel\" is singular.","D":"\"Its''\" is not a word."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.sv', 'medium', 0, 'mcq', 'The list of ingredients needed for the traditional holiday bread ______ surprisingly short, given how rich the finished loaf tastes: flour, water, salt, yeast, and a spoonful of honey.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"are"},{"id":"B","text":"were"},{"id":"C","text":"have been"},{"id":"D","text":"is"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The singular subject "list" takes the singular verb "is."', '{"A":"The subject is \"list,\" not \"ingredients.\"","B":"\"Were\" is plural and past.","C":"\"Have been\" is plural."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.modifier', 'hard', 1, 'mcq', 'The cathedral stands at the center of the old town, surrounded by narrow streets lined with shops and cafés. Built in the twelfth century and restored many times since, ______', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"thousands of visitors are still drawn to the cathedral each year."},{"id":"B","text":"visitors still come by the thousands to see the cathedral."},{"id":"C","text":"the cathedral still draws thousands of visitors each year."},{"id":"D","text":"each year the cathedral is visited by thousands."}]'::jsonb, '{"choice":"C"}'::jsonb, 'The modifier "Built… since" must be followed directly by what was built: the cathedral.', '{"A":"This says the visitors were built in the twelfth century.","B":"This says the visitors were built and restored.","D":"This places \"each year\" after the modifier, so it dangles."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.sv', 'hard', 1, 'mcq', 'Divers exploring the reef last summer made an unexpected discovery. Among the items found in the shipwreck ______ a brass compass, several clay jars, and a small wooden chest still sealed with wax.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"was"},{"id":"B","text":"is"},{"id":"C","text":"has been"},{"id":"D","text":"were"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The subject (compass, jars, chest) comes after the verb and is plural, so the verb is "were."', '{"A":"In this inverted sentence, the subject is the compound list that follows, which is plural.","B":"\"Is\" is singular and present.","C":"\"Has been\" is singular."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.sv', 'hard', 1, 'mcq', 'The Kellerman Museum is one of the few museums in the country that ______ their entire collections online, allowing anyone with an internet connection to view the artworks for free.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"display"},{"id":"B","text":"displays"},{"id":"C","text":"has displayed"},{"id":"D","text":"is displaying"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The clause describes the museums (plural) that display their collections, so the verb is "display."', '{"B":"\"That\" refers to the plural \"museums,\" so the verb must be plural.","C":"\"Has displayed\" is singular.","D":"\"Is displaying\" is singular."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.tense', 'hard', 1, 'mcq', 'The city council, after months of debate and several crowded public hearings, finally ______ to approve the plan for a new park on the city''s east side.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"voting"},{"id":"B","text":"having voted"},{"id":"C","text":"voted"},{"id":"D","text":"to vote"}]'::jsonb, '{"choice":"C"}'::jsonb, 'The sentence needs a finite main verb for the subject "council," and that is "voted."', '{"A":"\"Voting\" can''t serve as the main verb.","B":"\"Having voted\" can''t serve as the main verb.","D":"\"To vote\" can''t serve as the main verb."}'::jsonb),
  ('rw.sec.form', 'rw.sec.form.modifier', 'hard', 1, 'mcq', 'The trail climbed nearly a thousand meters in just four miles, and the afternoon sun was hotter than anyone had expected. Exhausted after the long climb, ______', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id":"A","text":"the lake was a welcome place for the hikers to rest."},{"id":"B","text":"resting beside the lake was what the hikers did."},{"id":"C","text":"a rest beside the lake refreshed the hikers."},{"id":"D","text":"the hikers rested beside the lake before starting down."}]'::jsonb, '{"choice":"D"}'::jsonb, 'The modifier "Exhausted after the long climb" must be followed directly by the people who were exhausted: the hikers.', '{"A":"This says the lake was exhausted.","B":"This says \"resting\" was exhausted.","C":"This says the rest was exhausted."}'::jsonb),
  ('math.alg.lin1', 'math.alg.lin1.solve', 'easy', -1, 'mcq', null, 'If $8x + 8 = 56$, what is the value of $x$?', '[{"id":"A","text":"$8$"},{"id":"B","text":"$48$"},{"id":"C","text":"$-6$"},{"id":"D","text":"$6$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Isolate the x-term: $8x = 56 - 8 = 48$. Divide both sides by 8: $x = 6$.', '{"A":"Moves 8 to the other side without changing its sign.","B":"Isolates 8x but forgets to divide by 8.","C":"Sign error when solving for x."}'::jsonb),
  ('math.alg.lin1', 'math.alg.lin1.solve', 'easy', -1, 'mcq', null, 'If $2x - 8 = -10$, what is the value of $x$?', '[{"id":"A","text":"$-1$"},{"id":"B","text":"$-9$"},{"id":"C","text":"$-2$"},{"id":"D","text":"$1$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Isolate the x-term: $2x = -10 + 8 = -2$. Divide both sides by 2: $x = -1$.', '{"B":"Moves -8 to the other side without changing its sign.","C":"Isolates 2x but forgets to divide by 2.","D":"Sign error when solving for x."}'::jsonb),
  ('math.alg.lin1', 'math.alg.lin1.solve', 'easy', -1, 'mcq', null, 'If $8x + 6 = 38$, what is the value of $x$?', '[{"id":"A","text":"$4$"},{"id":"B","text":"$32$"},{"id":"C","text":"$-4$"},{"id":"D","text":"$12$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Isolate the x-term: $8x = 38 - 6 = 32$. Divide both sides by 8: $x = 4$.', '{"B":"Isolates 8x but forgets to divide by 8.","C":"Sign error when solving for x.","D":"Arithmetic slip after isolating the x-term."}'::jsonb),
  ('math.alg.lin1', 'math.alg.lin1.solve', 'easy', -1, 'mcq', null, 'If $8x - 19 = -11$, what is the value of $x$?', '[{"id":"A","text":"$1$"},{"id":"B","text":"$8$"},{"id":"C","text":"$-1$"},{"id":"D","text":"$9$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Isolate the x-term: $8x = -11 + 19 = 8$. Divide both sides by 8: $x = 1$.', '{"B":"Isolates 8x but forgets to divide by 8.","C":"Sign error when solving for x.","D":"Arithmetic slip after isolating the x-term."}'::jsonb),
  ('math.alg.lin1', 'math.alg.lin1.solve', 'easy', -1, 'mcq', null, 'If $4x + 13 = 17$, what is the value of $x$?', '[{"id":"A","text":"$4$"},{"id":"B","text":"$1$"},{"id":"C","text":"$-1$"},{"id":"D","text":"$5$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Isolate the x-term: $4x = 17 - 13 = 4$. Divide both sides by 4: $x = 1$.', '{"A":"Isolates 4x but forgets to divide by 4.","C":"Sign error when solving for x.","D":"Arithmetic slip after isolating the x-term."}'::jsonb),
  ('math.alg.lin1', 'math.alg.lin1.solve', 'easy', -1, 'mcq', null, 'If $4x - 8 = 16$, what is the value of $x$?', '[{"id":"A","text":"$6$"},{"id":"B","text":"$2$"},{"id":"C","text":"$24$"},{"id":"D","text":"$-6$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Isolate the x-term: $4x = 16 + 8 = 24$. Divide both sides by 4: $x = 6$.', '{"B":"Moves -8 to the other side without changing its sign.","C":"Isolates 4x but forgets to divide by 4.","D":"Sign error when solving for x."}'::jsonb),
  ('math.alg.lin1', 'math.alg.lin1.solve', 'easy', -1, 'mcq', null, 'If $3x + 13 = -5$, what is the value of $x$?', '[{"id":"A","text":"$-18$"},{"id":"B","text":"$6$"},{"id":"C","text":"$-3$"},{"id":"D","text":"$-6$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Isolate the x-term: $3x = -5 - 13 = -18$. Divide both sides by 3: $x = -6$.', '{"A":"Isolates 3x but forgets to divide by 3.","B":"Sign error when solving for x.","C":"Arithmetic slip after isolating the x-term."}'::jsonb),
