  ('math.alg.lin2', 'math.alg.lin2.model', 'medium', 0, 'mcq', null, 'At a bake sale, muffins cost \$3 each and cookies cost \$4 each. A total of \$135 was collected from selling $x$ muffins and $y$ cookies. Which equation represents this situation?', '[{"id":"A","text":"$3x + 4y = 135$"},{"id":"B","text":"$4x + 3y = 135$"},{"id":"C","text":"$x + y = 135$"},{"id":"D","text":"$7(x + y) = 135$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Money from muffins is $3x$ and from cookies is $4y$; together they equal 135: $3x + 4y = 135$.', '{"B":"Swaps the two prices.","C":"Counts items sold rather than dollars collected.","D":"Assumes every item costs the combined price of both."}'::jsonb),
  ('math.alg.lin2', 'math.alg.lin2.model', 'medium', 0, 'mcq', null, 'At a club fundraiser, pens cost \$6 each and notebooks cost \$7 each. A total of \$266 was collected from selling $x$ pens and $y$ notebooks. Which equation represents this situation?', '[{"id":"A","text":"$7x + 6y = 266$"},{"id":"B","text":"$x + y = 266$"},{"id":"C","text":"$13(x + y) = 266$"},{"id":"D","text":"$6x + 7y = 266$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Money from pens is $6x$ and from notebooks is $7y$; together they equal 266: $6x + 7y = 266$.', '{"A":"Swaps the two prices.","B":"Counts items sold rather than dollars collected.","C":"Assumes every item costs the combined price of both."}'::jsonb),
  ('math.alg.lin2', 'math.alg.lin2.model', 'medium', 0, 'mcq', null, 'At a club fundraiser, pens cost \$2 each and notebooks cost \$4 each. A total of \$74 was collected from selling $x$ pens and $y$ notebooks. Which equation represents this situation?', '[{"id":"A","text":"$4x + 2y = 74$"},{"id":"B","text":"$x + y = 74$"},{"id":"C","text":"$2x + 4y = 74$"},{"id":"D","text":"$6(x + y) = 74$"}]'::jsonb, '{"choice":"C"}'::jsonb, 'Money from pens is $2x$ and from notebooks is $4y$; together they equal 74: $2x + 4y = 74$.', '{"A":"Swaps the two prices.","B":"Counts items sold rather than dollars collected.","D":"Assumes every item costs the combined price of both."}'::jsonb),
  ('math.alg.lin2', 'math.alg.lin2.model', 'medium', 0, 'mcq', null, 'At a bake sale, muffins cost \$5 each and cookies cost \$3 each. A total of \$112 was collected from selling $x$ muffins and $y$ cookies. Which equation represents this situation?', '[{"id":"A","text":"$5x + 3y = 112$"},{"id":"B","text":"$3x + 5y = 112$"},{"id":"C","text":"$x + y = 112$"},{"id":"D","text":"$8(x + y) = 112$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Money from muffins is $5x$ and from cookies is $3y$; together they equal 112: $5x + 3y = 112$.', '{"B":"Swaps the two prices.","C":"Counts items sold rather than dollars collected.","D":"Assumes every item costs the combined price of both."}'::jsonb),
  ('math.alg.lin2', 'math.alg.lin2.model', 'medium', 0, 'mcq', null, 'At a museum, student tickets cost \$7 each and adult tickets cost \$6 each. A total of \$328 was collected from selling $x$ student tickets and $y$ adult tickets. Which equation represents this situation?', '[{"id":"A","text":"$6x + 7y = 328$"},{"id":"B","text":"$7x + 6y = 328$"},{"id":"C","text":"$x + y = 328$"},{"id":"D","text":"$13(x + y) = 328$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Money from student tickets is $7x$ and from adult tickets is $6y$; together they equal 328: $7x + 6y = 328$.', '{"A":"Swaps the two prices.","C":"Counts items sold rather than dollars collected.","D":"Assumes every item costs the combined price of both."}'::jsonb),
  ('math.alg.lin2', 'math.alg.lin2.model', 'medium', 0, 'mcq', null, 'At a club fundraiser, pens cost \$8 each and notebooks cost \$2 each. A total of \$84 was collected from selling $x$ pens and $y$ notebooks. Which equation represents this situation?', '[{"id":"A","text":"$8x + 2y = 84$"},{"id":"B","text":"$2x + 8y = 84$"},{"id":"C","text":"$x + y = 84$"},{"id":"D","text":"$10(x + y) = 84$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Money from pens is $8x$ and from notebooks is $2y$; together they equal 84: $8x + 2y = 84$.', '{"B":"Swaps the two prices.","C":"Counts items sold rather than dollars collected.","D":"Assumes every item costs the combined price of both."}'::jsonb),
  ('math.alg.lin2', 'math.alg.lin2.model', 'medium', 0, 'mcq', null, 'At a museum, student tickets cost \$4 each and adult tickets cost \$5 each. A total of \$242 was collected from selling $x$ student tickets and $y$ adult tickets. Which equation represents this situation?', '[{"id":"A","text":"$5x + 4y = 242$"},{"id":"B","text":"$4x + 5y = 242$"},{"id":"C","text":"$x + y = 242$"},{"id":"D","text":"$9(x + y) = 242$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Money from student tickets is $4x$ and from adult tickets is $5y$; together they equal 242: $4x + 5y = 242$.', '{"A":"Swaps the two prices.","C":"Counts items sold rather than dollars collected.","D":"Assumes every item costs the combined price of both."}'::jsonb),
