  ('math.alg.linfn', 'math.alg.linfn.evaluate', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = -2x - 6$. What is the value of $f(6)$?', '[{"id":"A","text":"$-6$"},{"id":"B","text":"$0$"},{"id":"C","text":"$18$"},{"id":"D","text":"$-18$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Substitute 6 for x: $f(6) = -2(6) - 6 = -18$.', '{"A":"Uses the wrong sign for the constant term.","B":"Adds the constant before multiplying by the slope.","C":"Sign error in the final answer."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.evaluate', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = 5x + 10$. What is the value of $f(-3)$?', '[{"id":"A","text":"$-25$"},{"id":"B","text":"$-5$"},{"id":"C","text":"$35$"},{"id":"D","text":"$5$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Substitute -3 for x: $f(-3) = 5(-3) + 10 = -5$.', '{"A":"Uses the wrong sign for the constant term.","C":"Adds the constant before multiplying by the slope.","D":"Sign error in the final answer."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.evaluate', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = -x - 5$. What is the value of $f(-1)$?', '[{"id":"A","text":"$6$"},{"id":"B","text":"$4$"},{"id":"C","text":"$-7$"},{"id":"D","text":"$-4$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Substitute -1 for x: $f(-1) = -1(-1) - 5 = -4$.', '{"A":"Uses the wrong sign for the constant term.","B":"Sign error in the final answer.","C":"Adds the input instead of multiplying by it."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.evaluate', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = -5x + 5$. What is the value of $f(6)$?', '[{"id":"A","text":"$-35$"},{"id":"B","text":"$-55$"},{"id":"C","text":"$-25$"},{"id":"D","text":"$25$"}]'::jsonb, '{"choice":"C"}'::jsonb, 'Substitute 6 for x: $f(6) = -5(6) + 5 = -25$.', '{"A":"Uses the wrong sign for the constant term.","B":"Adds the constant before multiplying by the slope.","D":"Sign error in the final answer."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.evaluate', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = -5x + 2$. What is the value of $f(-4)$?', '[{"id":"A","text":"$18$"},{"id":"B","text":"$10$"},{"id":"C","text":"$-22$"},{"id":"D","text":"$22$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Substitute -4 for x: $f(-4) = -5(-4) + 2 = 22$.', '{"A":"Uses the wrong sign for the constant term.","B":"Adds the constant before multiplying by the slope.","C":"Sign error in the final answer."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.evaluate', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = x + 4$. What is the value of $f(2)$?', '[{"id":"A","text":"$-2$"},{"id":"B","text":"$-6$"},{"id":"C","text":"$6$"},{"id":"D","text":"$7$"}]'::jsonb, '{"choice":"C"}'::jsonb, 'Substitute 2 for x: $f(2) = 1(2) + 4 = 6$.', '{"A":"Uses the wrong sign for the constant term.","B":"Sign error in the final answer.","D":"Adds the input instead of multiplying by it."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.evaluate', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = -4x + 5$. What is the value of $f(-5)$?', '[{"id":"A","text":"$25$"},{"id":"B","text":"$15$"},{"id":"C","text":"$0$"},{"id":"D","text":"$-25$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Substitute -5 for x: $f(-5) = -4(-5) + 5 = 25$.', '{"B":"Uses the wrong sign for the constant term.","C":"Adds the constant before multiplying by the slope.","D":"Sign error in the final answer."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.represent', 'medium', 0, 'mcq', null, 'For the linear function $f$, $f(1) = -1$ and $f(3) = 7$. Which equation defines $f$?', '[{"id":"A","text":"$f(x) = 4x - 5$"},{"id":"B","text":"$f(x) = 4x - 1$"},{"id":"C","text":"$f(x) = -5x + 4$"},{"id":"D","text":"$f(x) = 4x + 5$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Slope: $\frac{7 - (-1)}{3 - 1} = 4$. Then $-1 = 4(1) + b$ gives $b = -5$, so $f(x) = 4x - 5$.', '{"B":"Uses f(1) as the y-intercept.","C":"Swaps the slope and the y-intercept.","D":"Uses the wrong sign for the y-intercept."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.represent', 'medium', 0, 'mcq', null, 'For the linear function $f$, $f(2) = -19$ and $f(3) = -24$. Which equation defines $f$?', '[{"id":"A","text":"$f(x) = -5x - 19$"},{"id":"B","text":"$f(x) = -9x - 5$"},{"id":"C","text":"$f(x) = -5x + 9$"},{"id":"D","text":"$f(x) = -5x - 9$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Slope: $\frac{-24 - (-19)}{3 - 2} = -5$. Then $-19 = -5(2) + b$ gives $b = -9$, so $f(x) = -5x - 9$.', '{"A":"Uses f(2) as the y-intercept.","B":"Swaps the slope and the y-intercept.","C":"Uses the wrong sign for the y-intercept."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.represent', 'medium', 0, 'mcq', null, 'For the linear function $f$, $f(3) = -21$ and $f(7) = -41$. Which equation defines $f$?', '[{"id":"A","text":"$f(x) = -5x - 21$"},{"id":"B","text":"$f(x) = -6x - 5$"},{"id":"C","text":"$f(x) = -5x - 6$"},{"id":"D","text":"$f(x) = -5x + 6$"}]'::jsonb, '{"choice":"C"}'::jsonb, 'Slope: $\frac{-41 - (-21)}{7 - 3} = -5$. Then $-21 = -5(3) + b$ gives $b = -6$, so $f(x) = -5x - 6$.', '{"A":"Uses f(3) as the y-intercept.","B":"Swaps the slope and the y-intercept.","D":"Uses the wrong sign for the y-intercept."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.represent', 'medium', 0, 'mcq', null, 'For the linear function $f$, $f(2) = 16$ and $f(5) = 28$. Which equation defines $f$?', '[{"id":"A","text":"$f(x) = 4x + 16$"},{"id":"B","text":"$f(x) = 8x + 4$"},{"id":"C","text":"$f(x) = 4x - 8$"},{"id":"D","text":"$f(x) = 4x + 8$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Slope: $\frac{28 - (16)}{5 - 2} = 4$. Then $16 = 4(2) + b$ gives $b = 8$, so $f(x) = 4x + 8$.', '{"A":"Uses f(2) as the y-intercept.","B":"Swaps the slope and the y-intercept.","C":"Uses the wrong sign for the y-intercept."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.represent', 'medium', 0, 'mcq', null, 'For the linear function $f$, $f(2) = 1$ and $f(6) = -15$. Which equation defines $f$?', '[{"id":"A","text":"$f(x) = -4x + 9$"},{"id":"B","text":"$f(x) = -4x + 1$"},{"id":"C","text":"$f(x) = 9x - 4$"},{"id":"D","text":"$f(x) = -4x - 9$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Slope: $\frac{-15 - (1)}{6 - 2} = -4$. Then $1 = -4(2) + b$ gives $b = 9$, so $f(x) = -4x + 9$.', '{"B":"Uses f(2) as the y-intercept.","C":"Swaps the slope and the y-intercept.","D":"Uses the wrong sign for the y-intercept."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.represent', 'medium', 0, 'mcq', null, 'For the linear function $f$, $f(1) = 6$ and $f(4) = 9$. Which equation defines $f$?', '[{"id":"A","text":"$f(x) = x + 6$"},{"id":"B","text":"$f(x) = 5x + 1$"},{"id":"C","text":"$f(x) = x - 5$"},{"id":"D","text":"$f(x) = x + 5$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Slope: $\frac{9 - (6)}{4 - 1} = 1$. Then $6 = 1(1) + b$ gives $b = 5$, so $f(x) = x + 5$.', '{"A":"Uses f(1) as the y-intercept.","B":"Swaps the slope and the y-intercept.","C":"Uses the wrong sign for the y-intercept."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.represent', 'medium', 0, 'mcq', null, 'For the linear function $f$, $f(3) = -9$ and $f(5) = -17$. Which equation defines $f$?', '[{"id":"A","text":"$f(x) = -4x + 3$"},{"id":"B","text":"$f(x) = -4x - 9$"},{"id":"C","text":"$f(x) = 3x - 4$"},{"id":"D","text":"$f(x) = -4x - 3$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Slope: $\frac{-17 - (-9)}{5 - 3} = -4$. Then $-9 = -4(3) + b$ gives $b = 3$, so $f(x) = -4x + 3$.', '{"B":"Uses f(3) as the y-intercept.","C":"Swaps the slope and the y-intercept.","D":"Uses the wrong sign for the y-intercept."}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.interpret', 'hard', 1, 'spr', null, 'The function $f$ is defined by $f(x) = 3x + 4$. The function $g$ is defined by $g(x) = f(x - 3) - 1$. What is the value of $g(2)$?', null, '{"values":[[0,1]],"display":"0"}'::jsonb, '$g(2) = f(2 - 3) - 1 = f(-1) - 1$. Since $f(-1) = 3(-1) + 4 = 1$, $g(2) = 1 - 1 = 0$.', '{}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.interpret', 'hard', 1, 'spr', null, 'The function $f$ is defined by $f(x) = -4x - 2$. The function $g$ is defined by $g(x) = f(x - 3) - 2$. What is the value of $g(2)$?', null, '{"values":[[0,1]],"display":"0"}'::jsonb, '$g(2) = f(2 - 3) - 2 = f(-1) - 2$. Since $f(-1) = -4(-1) - 2 = 2$, $g(2) = 2 - 2 = 0$.', '{}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.interpret', 'hard', 1, 'spr', null, 'The function $f$ is defined by $f(x) = 3x - 5$. The function $g$ is defined by $g(x) = f(x + 4) + 5$. What is the value of $g(5)$?', null, '{"values":[[27,1]],"display":"27"}'::jsonb, '$g(5) = f(5 + 4) + 5 = f(9) + 5$. Since $f(9) = 3(9) - 5 = 22$, $g(5) = 22 + 5 = 27$.', '{}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.interpret', 'hard', 1, 'spr', null, 'The function $f$ is defined by $f(x) = x - 3$. The function $g$ is defined by $g(x) = f(x - 1) + 2$. What is the value of $g(-2)$?', null, '{"values":[[-4,1]],"display":"-4"}'::jsonb, '$g(-2) = f(-2 - 1) + 2 = f(-3) + 2$. Since $f(-3) = 1(-3) - 3 = -6$, $g(-2) = -6 + 2 = -4$.', '{}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.interpret', 'hard', 1, 'spr', null, 'The function $f$ is defined by $f(x) = 5x - 4$. The function $g$ is defined by $g(x) = f(x - 4) + 1$. What is the value of $g(5)$?', null, '{"values":[[2,1]],"display":"2"}'::jsonb, '$g(5) = f(5 - 4) + 1 = f(1) + 1$. Since $f(1) = 5(1) - 4 = 1$, $g(5) = 1 + 1 = 2$.', '{}'::jsonb),
  ('math.alg.linfn', 'math.alg.linfn.interpret', 'hard', 1, 'spr', null, 'The function $f$ is defined by $f(x) = -5x - 2$. The function $g$ is defined by $g(x) = f(x + 1) - 2$. What is the value of $g(4)$?', null, '{"values":[[-29,1]],"display":"-29"}'::jsonb, '$g(4) = f(4 + 1) - 2 = f(5) - 2$. Since $f(5) = -5(5) - 2 = -27$, $g(4) = -27 - 2 = -29$.', '{}'::jsonb),
