  ('math.psda.percent', 'math.psda.percent.change', 'hard', 1, 'mcq', null, 'A store increased the price of a jacket by 10%. Later, it decreased the new price by 50%. Which statement describes the final price compared with the original price?', '[{"id":"A","text":"It decreased by 40%."},{"id":"B","text":"It increased by 45%."},{"id":"C","text":"It decreased by 45%."},{"id":"D","text":"It increased by 60%."}]'::jsonb, '{"choice":"C"}'::jsonb, 'Multiply the factors: $1.1 \times 0.5 = 0.55$. So the final price is 55% of the original: it decreased by 45%.', '{"A":"Adds the percents directly; the second change applies to the new, different amount.","B":"Gets the size of the net change right but the direction wrong.","D":"Treats both changes as increases."}'::jsonb),
  ('math.psda.percent', 'math.psda.percent.change', 'hard', 1, 'mcq', null, 'A store increased the price of a jacket by 10%. Later, it decreased the new price by 10%. Which statement describes the final price compared with the original price?', '[{"id":"A","text":"It did not change."},{"id":"B","text":"It increased by 1%."},{"id":"C","text":"It increased by 20%."},{"id":"D","text":"It decreased by 1%."}]'::jsonb, '{"choice":"D"}'::jsonb, 'Multiply the factors: $1.1 \times 0.9 = 0.99$. So the final price is 99% of the original: it decreased by 1%.', '{"A":"Adds the percents directly; the second change applies to the new, different amount.","B":"Gets the size of the net change right but the direction wrong.","C":"Treats both changes as increases."}'::jsonb),
