  ('math.geo.trig', 'math.geo.trig.pythagorean', 'easy', -1, 'mcq', null, 'A right triangle has legs of lengths 21 and 72. What is the length of the hypotenuse?', '[{"id":"A","text":"$93$"},{"id":"B","text":"$75$"},{"id":"C","text":"$5625$"},{"id":"D","text":"$51$"}]'::jsonb, '{"choice":"B"}'::jsonb, '$c^2 = 21^2 + 72^2 = 441 + 5184 = 5625$, so $c = 75$.', '{"A":"Adds the legs; the Pythagorean theorem adds their squares.","C":"Forgets to take the square root.","D":"Subtracts the legs."}'::jsonb),
  ('math.geo.trig', 'math.geo.trig.pythagorean', 'easy', -1, 'mcq', null, 'A right triangle has legs of lengths 16 and 30. What is the length of the hypotenuse?', '[{"id":"A","text":"$46$"},{"id":"B","text":"$1156$"},{"id":"C","text":"$14$"},{"id":"D","text":"$34$"}]'::jsonb, '{"choice":"D"}'::jsonb, '$c^2 = 16^2 + 30^2 = 256 + 900 = 1156$, so $c = 34$.', '{"A":"Adds the legs; the Pythagorean theorem adds their squares.","B":"Forgets to take the square root.","C":"Subtracts the legs."}'::jsonb),
  ('math.geo.trig', 'math.geo.trig.pythagorean', 'easy', -1, 'mcq', null, 'A right triangle has legs of lengths 5 and 12. What is the length of the hypotenuse?', '[{"id":"A","text":"$13$"},{"id":"B","text":"$17$"},{"id":"C","text":"$169$"},{"id":"D","text":"$7$"}]'::jsonb, '{"choice":"A"}'::jsonb, '$c^2 = 5^2 + 12^2 = 25 + 144 = 169$, so $c = 13$.', '{"B":"Adds the legs; the Pythagorean theorem adds their squares.","C":"Forgets to take the square root.","D":"Subtracts the legs."}'::jsonb),
  ('math.geo.trig', 'math.geo.trig.pythagorean', 'easy', -1, 'mcq', null, 'A right triangle has legs of lengths 9 and 12. What is the length of the hypotenuse?', '[{"id":"A","text":"$21$"},{"id":"B","text":"$225$"},{"id":"C","text":"$15$"},{"id":"D","text":"$3$"}]'::jsonb, '{"choice":"C"}'::jsonb, '$c^2 = 9^2 + 12^2 = 81 + 144 = 225$, so $c = 15$.', '{"A":"Adds the legs; the Pythagorean theorem adds their squares.","B":"Forgets to take the square root.","D":"Subtracts the legs."}'::jsonb),
  ('math.geo.trig', 'math.geo.trig.pythagorean', 'easy', -1, 'mcq', null, 'A right triangle has legs of lengths 6 and 8. What is the length of the hypotenuse?', '[{"id":"A","text":"$14$"},{"id":"B","text":"$10$"},{"id":"C","text":"$100$"},{"id":"D","text":"$2$"}]'::jsonb, '{"choice":"B"}'::jsonb, '$c^2 = 6^2 + 8^2 = 36 + 64 = 100$, so $c = 10$.', '{"A":"Adds the legs; the Pythagorean theorem adds their squares.","C":"Forgets to take the square root.","D":"Subtracts the legs."}'::jsonb),
