  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'easy', -1, 'mcq', null, 'Which expression is equivalent to $(x - 3)(x - 4)$?', '[{"id":"A","text":"$x^2 + 12$"},{"id":"B","text":"$x^2 + 12x - 7$"},{"id":"C","text":"$x^2 - 7x - 12$"},{"id":"D","text":"$x^2 - 7x + 12$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Distribute: $x^2 + -3x + -4x + (-3)(-4) = x^2 - 7x + 12$.', '{"A":"Multiplies only the first terms and the last terms, dropping the middle term.","B":"Swaps the sum and the product of the constants.","C":"Uses the wrong sign for the constant term."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'easy', -1, 'mcq', null, 'Which expression is equivalent to $(x - 2)(x + 5)$?', '[{"id":"A","text":"$x^2 - 10$"},{"id":"B","text":"$x^2 + 3x - 10$"},{"id":"C","text":"$x^2 - 10x + 3$"},{"id":"D","text":"$x^2 + 3x + 10$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Distribute: $x^2 + -2x + 5x + (-2)(5) = x^2 + 3x - 10$.', '{"A":"Multiplies only the first terms and the last terms, dropping the middle term.","C":"Swaps the sum and the product of the constants.","D":"Uses the wrong sign for the constant term."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'easy', -1, 'mcq', null, 'Which expression is equivalent to $(x - 8)(x - 9)$?', '[{"id":"A","text":"$x^2 - 17x + 72$"},{"id":"B","text":"$x^2 + 72$"},{"id":"C","text":"$x^2 + 72x - 17$"},{"id":"D","text":"$x^2 - 17x - 72$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Distribute: $x^2 + -8x + -9x + (-8)(-9) = x^2 - 17x + 72$.', '{"B":"Multiplies only the first terms and the last terms, dropping the middle term.","C":"Swaps the sum and the product of the constants.","D":"Uses the wrong sign for the constant term."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'easy', -1, 'mcq', null, 'Which expression is equivalent to $(x + 9)(x - 2)$?', '[{"id":"A","text":"$x^2 - 18$"},{"id":"B","text":"$x^2 + 7x - 18$"},{"id":"C","text":"$x^2 - 18x + 7$"},{"id":"D","text":"$x^2 + 7x + 18$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Distribute: $x^2 + 9x + -2x + (9)(-2) = x^2 + 7x - 18$.', '{"A":"Multiplies only the first terms and the last terms, dropping the middle term.","C":"Swaps the sum and the product of the constants.","D":"Uses the wrong sign for the constant term."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'easy', -1, 'mcq', null, 'Which expression is equivalent to $(x - 5)(x - 7)$?', '[{"id":"A","text":"$x^2 - 12x + 35$"},{"id":"B","text":"$x^2 + 35$"},{"id":"C","text":"$x^2 + 35x - 12$"},{"id":"D","text":"$x^2 - 12x - 35$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Distribute: $x^2 + -5x + -7x + (-5)(-7) = x^2 - 12x + 35$.', '{"B":"Multiplies only the first terms and the last terms, dropping the middle term.","C":"Swaps the sum and the product of the constants.","D":"Uses the wrong sign for the constant term."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'easy', -1, 'mcq', null, 'Which expression is equivalent to $(x + 3)(x + 7)$?', '[{"id":"A","text":"$x^2 + 21$"},{"id":"B","text":"$x^2 + 21x + 10$"},{"id":"C","text":"$x^2 + 10x + 21$"},{"id":"D","text":"$x^2 + 10x - 21$"}]'::jsonb, '{"choice":"C"}'::jsonb, 'Distribute: $x^2 + 3x + 7x + (3)(7) = x^2 + 10x + 21$.', '{"A":"Multiplies only the first terms and the last terms, dropping the middle term.","B":"Swaps the sum and the product of the constants.","D":"Uses the wrong sign for the constant term."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'easy', -1, 'mcq', null, 'Which expression is equivalent to $(x - 5)(x - 1)$?', '[{"id":"A","text":"$x^2 + 5$"},{"id":"B","text":"$x^2 - 6x + 5$"},{"id":"C","text":"$x^2 + 5x - 6$"},{"id":"D","text":"$x^2 - 6x - 5$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Distribute: $x^2 + -5x + -1x + (-5)(-1) = x^2 - 6x + 5$.', '{"A":"Multiplies only the first terms and the last terms, dropping the middle term.","C":"Swaps the sum and the product of the constants.","D":"Uses the wrong sign for the constant term."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'medium', 0, 'mcq', null, 'Which expression is equivalent to $6x^2 - 216$?', '[{"id":"A","text":"$6(x - 6)^2$"},{"id":"B","text":"$6(x - 6)(x + 6)$"},{"id":"C","text":"$(6x - 6)(6x + 6)$"},{"id":"D","text":"$6(x - 36)(x + 36)$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Factor out 6: $6(x^2 - 36)$. Then use the difference of squares: $6(x - 6)(x + 6)$.', '{"A":"A squared binomial has a middle term; the given expression has none.","C":"This expands to 36x² − 36, not 6x² − 216.","D":"Uses 36 instead of its square root inside the factors."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'medium', 0, 'mcq', null, 'Which expression is equivalent to $5x^2 - 20$?', '[{"id":"A","text":"$5(x - 2)^2$"},{"id":"B","text":"$5(x - 2)(x + 2)$"},{"id":"C","text":"$(5x - 2)(5x + 2)$"},{"id":"D","text":"$5(x - 4)(x + 4)$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Factor out 5: $5(x^2 - 4)$. Then use the difference of squares: $5(x - 2)(x + 2)$.', '{"A":"A squared binomial has a middle term; the given expression has none.","C":"This expands to 25x² − 4, not 5x² − 20.","D":"Uses 4 instead of its square root inside the factors."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'medium', 0, 'mcq', null, 'Which expression is equivalent to $4x^2 - 36$?', '[{"id":"A","text":"$4(x - 3)^2$"},{"id":"B","text":"$4(x - 3)(x + 3)$"},{"id":"C","text":"$(4x - 3)(4x + 3)$"},{"id":"D","text":"$4(x - 9)(x + 9)$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'Factor out 4: $4(x^2 - 9)$. Then use the difference of squares: $4(x - 3)(x + 3)$.', '{"A":"A squared binomial has a middle term; the given expression has none.","C":"This expands to 16x² − 9, not 4x² − 36.","D":"Uses 9 instead of its square root inside the factors."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'medium', 0, 'mcq', null, 'Which expression is equivalent to $3x^2 - 192$?', '[{"id":"A","text":"$3(x - 8)(x + 8)$"},{"id":"B","text":"$3(x - 8)^2$"},{"id":"C","text":"$(3x - 8)(3x + 8)$"},{"id":"D","text":"$3(x - 64)(x + 64)$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Factor out 3: $3(x^2 - 64)$. Then use the difference of squares: $3(x - 8)(x + 8)$.', '{"B":"A squared binomial has a middle term; the given expression has none.","C":"This expands to 9x² − 64, not 3x² − 192.","D":"Uses 64 instead of its square root inside the factors."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'medium', 0, 'mcq', null, 'Which expression is equivalent to $6x^2 - 24$?', '[{"id":"A","text":"$6(x - 2)(x + 2)$"},{"id":"B","text":"$6(x - 2)^2$"},{"id":"C","text":"$(6x - 2)(6x + 2)$"},{"id":"D","text":"$6(x - 4)(x + 4)$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'Factor out 6: $6(x^2 - 4)$. Then use the difference of squares: $6(x - 2)(x + 2)$.', '{"B":"A squared binomial has a middle term; the given expression has none.","C":"This expands to 36x² − 4, not 6x² − 24.","D":"Uses 4 instead of its square root inside the factors."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'medium', 0, 'mcq', null, 'Which expression is equivalent to $5x^2 - 245$?', '[{"id":"A","text":"$5(x - 7)^2$"},{"id":"B","text":"$(5x - 7)(5x + 7)$"},{"id":"C","text":"$5(x - 49)(x + 49)$"},{"id":"D","text":"$5(x - 7)(x + 7)$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Factor out 5: $5(x^2 - 49)$. Then use the difference of squares: $5(x - 7)(x + 7)$.', '{"A":"A squared binomial has a middle term; the given expression has none.","B":"This expands to 25x² − 49, not 5x² − 245.","C":"Uses 49 instead of its square root inside the factors."}'::jsonb),
  ('math.adv.equiv', 'math.adv.equiv.polynomial', 'medium', 0, 'mcq', null, 'Which expression is equivalent to $6x^2 - 384$?', '[{"id":"A","text":"$6(x - 8)^2$"},{"id":"B","text":"$(6x - 8)(6x + 8)$"},{"id":"C","text":"$6(x - 64)(x + 64)$"},{"id":"D","text":"$6(x - 8)(x + 8)$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'Factor out 6: $6(x^2 - 64)$. Then use the difference of squares: $6(x - 8)(x + 8)$.', '{"A":"A squared binomial has a middle term; the given expression has none.","B":"This expands to 36x² − 64, not 6x² − 384.","C":"Uses 64 instead of its square root inside the factors."}'::jsonb),
