  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = 4x^2 - 10$. What is the value of $f(3)$?', '[{"id":"A","text":"$134$"},{"id":"B","text":"$14$"},{"id":"C","text":"$26$"},{"id":"D","text":"$46$"}]'::jsonb, '{"choice":"C"}'::jsonb, '$f(3) = 4(3)^2 - 10 = 4(9) - 10 = 26$.', '{"A":"Squares 4·3 instead of only 3.","B":"Multiplies by 2 instead of squaring.","D":"Uses the wrong sign for the constant."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = 5x^2 + 4$. What is the value of $f(-3)$?', '[{"id":"A","text":"$229$"},{"id":"B","text":"$-26$"},{"id":"C","text":"$49$"},{"id":"D","text":"$41$"}]'::jsonb, '{"choice":"C"}'::jsonb, '$f(-3) = 5(-3)^2 + 4 = 5(9) + 4 = 49$.', '{"A":"Squares 5·-3 instead of only -3.","B":"Multiplies by 2 instead of squaring.","D":"Uses the wrong sign for the constant."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = 2x^2 - 11$. What is the value of $f(-1)$?', '[{"id":"A","text":"$-7$"},{"id":"B","text":"$-15$"},{"id":"C","text":"$13$"},{"id":"D","text":"$-9$"}]'::jsonb, '{"choice":"D"}'::jsonb, '$f(-1) = 2(-1)^2 - 11 = 2(1) - 11 = -9$.', '{"A":"Squares 2·-1 instead of only -1.","B":"Multiplies by 2 instead of squaring.","C":"Uses the wrong sign for the constant."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = -4x^2 + 1$. What is the value of $f(-1)$?', '[{"id":"A","text":"$17$"},{"id":"B","text":"$9$"},{"id":"C","text":"$-3$"},{"id":"D","text":"$-5$"}]'::jsonb, '{"choice":"C"}'::jsonb, '$f(-1) = -4(-1)^2 + 1 = -4(1) + 1 = -3$.', '{"A":"Squares -4·-1 instead of only -1.","B":"Multiplies by 2 instead of squaring.","D":"Uses the wrong sign for the constant."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = 3x^2 - 5$. What is the value of $f(-1)$?', '[{"id":"A","text":"$4$"},{"id":"B","text":"$-2$"},{"id":"C","text":"$-11$"},{"id":"D","text":"$8$"}]'::jsonb, '{"choice":"B"}'::jsonb, '$f(-1) = 3(-1)^2 - 5 = 3(1) - 5 = -2$.', '{"A":"Squares 3·-1 instead of only -1.","C":"Multiplies by 2 instead of squaring.","D":"Uses the wrong sign for the constant."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = -3x^2 - 8$. What is the value of $f(-4)$?', '[{"id":"A","text":"$136$"},{"id":"B","text":"$16$"},{"id":"C","text":"$-56$"},{"id":"D","text":"$-40$"}]'::jsonb, '{"choice":"C"}'::jsonb, '$f(-4) = -3(-4)^2 - 8 = -3(16) - 8 = -56$.', '{"A":"Squares -3·-4 instead of only -4.","B":"Multiplies by 2 instead of squaring.","D":"Uses the wrong sign for the constant."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'easy', -1, 'mcq', null, 'The function $f$ is defined by $f(x) = -3x^2 + 11$. What is the value of $f(2)$?', '[{"id":"A","text":"$47$"},{"id":"B","text":"$-1$"},{"id":"C","text":"$-23$"},{"id":"D","text":"$1$"}]'::jsonb, '{"choice":"B"}'::jsonb, '$f(2) = -3(2)^2 + 11 = -3(4) + 11 = -1$.', '{"A":"Squares -3·2 instead of only 2.","C":"Uses the wrong sign for the constant.","D":"Sign error in the final answer."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'medium', 0, 'mcq', null, 'The function $f$ is defined by $f(x) = (x + 6)^2 + 13$. What is the minimum value of $f(x)$?', '[{"id":"A","text":"$-6$"},{"id":"B","text":"$13$"},{"id":"C","text":"$-13$"},{"id":"D","text":"$6$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'In vertex form $a(x - h)^2 + k$ with $a > 0$, the minimum value is $k$. Here the squared term is at least 0, so $f(x)$ is smallest at $x = -6$, where $f(-6) = 13$.', '{"A":"This is the x-coordinate of the vertex, not the minimum value.","C":"Uses the wrong sign for the vertex’s y-coordinate.","D":"Reads the x-coordinate from the factor with the wrong sign."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'medium', 0, 'mcq', null, 'The function $f$ is defined by $f(x) = (x - 3)^2 + 12$. What is the minimum value of $f(x)$?', '[{"id":"A","text":"$12$"},{"id":"B","text":"$3$"},{"id":"C","text":"$-12$"},{"id":"D","text":"$-3$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'In vertex form $a(x - h)^2 + k$ with $a > 0$, the minimum value is $k$. Here the squared term is at least 0, so $f(x)$ is smallest at $x = 3$, where $f(3) = 12$.', '{"B":"This is the x-coordinate of the vertex, not the minimum value.","C":"Uses the wrong sign for the vertex’s y-coordinate.","D":"Reads the x-coordinate from the factor with the wrong sign."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'medium', 0, 'mcq', null, 'The function $f$ is defined by $f(x) = 4(x + 1)^2 + 12$. What is the minimum value of $f(x)$?', '[{"id":"A","text":"$-1$"},{"id":"B","text":"$12$"},{"id":"C","text":"$-12$"},{"id":"D","text":"$1$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'In vertex form $a(x - h)^2 + k$ with $a > 0$, the minimum value is $k$. Here the squared term is at least 0, so $f(x)$ is smallest at $x = -1$, where $f(-1) = 12$.', '{"A":"This is the x-coordinate of the vertex, not the minimum value.","C":"Uses the wrong sign for the vertex’s y-coordinate.","D":"Reads the x-coordinate from the factor with the wrong sign."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'medium', 0, 'mcq', null, 'The function $f$ is defined by $f(x) = 2(x - 5)^2 + 6$. What is the minimum value of $f(x)$?', '[{"id":"A","text":"$5$"},{"id":"B","text":"$6$"},{"id":"C","text":"$-6$"},{"id":"D","text":"$-5$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'In vertex form $a(x - h)^2 + k$ with $a > 0$, the minimum value is $k$. Here the squared term is at least 0, so $f(x)$ is smallest at $x = 5$, where $f(5) = 6$.', '{"A":"This is the x-coordinate of the vertex, not the minimum value.","C":"Uses the wrong sign for the vertex’s y-coordinate.","D":"Reads the x-coordinate from the factor with the wrong sign."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'medium', 0, 'mcq', null, 'The function $f$ is defined by $f(x) = 4(x + 7)^2 + 3$. What is the minimum value of $f(x)$?', '[{"id":"A","text":"$3$"},{"id":"B","text":"$-7$"},{"id":"C","text":"$-3$"},{"id":"D","text":"$7$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'In vertex form $a(x - h)^2 + k$ with $a > 0$, the minimum value is $k$. Here the squared term is at least 0, so $f(x)$ is smallest at $x = -7$, where $f(-7) = 3$.', '{"B":"This is the x-coordinate of the vertex, not the minimum value.","C":"Uses the wrong sign for the vertex’s y-coordinate.","D":"Reads the x-coordinate from the factor with the wrong sign."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'medium', 0, 'mcq', null, 'The function $f$ is defined by $f(x) = 2(x - 7)^2 + 11$. What is the minimum value of $f(x)$?', '[{"id":"A","text":"$7$"},{"id":"B","text":"$11$"},{"id":"C","text":"$-11$"},{"id":"D","text":"$-7$"}]'::jsonb, '{"choice":"B"}'::jsonb, 'In vertex form $a(x - h)^2 + k$ with $a > 0$, the minimum value is $k$. Here the squared term is at least 0, so $f(x)$ is smallest at $x = 7$, where $f(7) = 11$.', '{"A":"This is the x-coordinate of the vertex, not the minimum value.","C":"Uses the wrong sign for the vertex’s y-coordinate.","D":"Reads the x-coordinate from the factor with the wrong sign."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.quadratic', 'medium', 0, 'mcq', null, 'The function $f$ is defined by $f(x) = (x - 6)^2 - 8$. What is the minimum value of $f(x)$?', '[{"id":"A","text":"$6$"},{"id":"B","text":"$8$"},{"id":"C","text":"$-8$"},{"id":"D","text":"$-6$"}]'::jsonb, '{"choice":"C"}'::jsonb, 'In vertex form $a(x - h)^2 + k$ with $a > 0$, the minimum value is $k$. Here the squared term is at least 0, so $f(x)$ is smallest at $x = 6$, where $f(6) = -8$.', '{"A":"This is the x-coordinate of the vertex, not the minimum value.","B":"Uses the wrong sign for the vertex’s y-coordinate.","D":"Reads the x-coordinate from the factor with the wrong sign."}'::jsonb),
  ('math.adv.nonlin_fn', 'math.adv.nonlin_fn.exponential', 'hard', 1, 'spr', null, 'The number of trees in a reforestation plot is 150 and doubles every 7 months. If this pattern continues, what will the number be after 21 months?', null, '{"values":[[1200,1]],"display":"1200"}'::jsonb, '21 is 3 periods of 7, so the number is multiplied by 2 a total of 3 times: $150 \cdot 2^{3} = 1200$.', '{}'::jsonb),
