  ('math.psda.ratios', 'math.psda.ratios.proportion', 'easy', -1, 'mcq', null, 'A recipe uses 3 cups of flour to make 20 cookies. At this rate, how many cups of flour are needed to make 100 cookies?', '[{"id":"A","text":"$15$"},{"id":"B","text":"$8$"},{"id":"C","text":"$60$"},{"id":"D","text":"$80$"}]'::jsonb, '{"choice":"A"}'::jsonb, '100 cookies is $\frac{100}{20} = 5$ times the recipe, so the flour is $3 \cdot 5 = 15$ cups.', '{"B":"Adds the scale factor instead of multiplying.","C":"Multiplies the two numbers in the original recipe.","D":"Subtracts the cookie counts instead of scaling."}'::jsonb),
  ('math.psda.ratios', 'math.psda.ratios.proportion', 'easy', -1, 'mcq', null, 'A recipe uses 5 cups of flour to make 30 cookies. At this rate, how many cups of flour are needed to make 60 cookies?', '[{"id":"A","text":"$7$"},{"id":"B","text":"$10$"},{"id":"C","text":"$12$"},{"id":"D","text":"$150$"}]'::jsonb, '{"choice":"B"}'::jsonb, '60 cookies is $\frac{60}{30} = 2$ times the recipe, so the flour is $5 \cdot 2 = 10$ cups.', '{"A":"Adds the scale factor instead of multiplying.","C":"Divides the number of cookies by the cups of flour.","D":"Multiplies the two numbers in the original recipe."}'::jsonb),
