  ('math.geo.area', 'math.geo.area.area', 'easy', -1, 'mcq', null, 'A triangle has a base of 8 centimeters and a height of 10 centimeters. What is the area of the triangle, in square centimeters?', '[{"id":"A","text":"$80$"},{"id":"B","text":"$18$"},{"id":"C","text":"$40$"},{"id":"D","text":"$36$"}]'::jsonb, '{"choice":"C"}'::jsonb, '$A = \frac{1}{2}bh = \frac{1}{2}(8)(10) = 40$.', '{"A":"Forgets the factor of 1/2 in the triangle area formula.","B":"Adds the base and height.","D":"Computes a perimeter-like quantity, not area."}'::jsonb),
