  ('math.geo.lines', 'math.geo.lines.similar', 'hard', 1, 'mcq', null, 'Triangle $ABC$ is similar to triangle $DEF$, where $A$, $B$, and $C$ correspond to $D$, $E$, and $F$. If $AB = 12$, $BC = 16$, and $DE = 36$, what is $EF$?', '[{"id":"A","text":"$40$"},{"id":"B","text":"$27$"},{"id":"C","text":"$144$"},{"id":"D","text":"$48$"}]'::jsonb, '{"choice":"D"}'::jsonb, 'The scale factor is $\frac{DE}{AB} = \frac{36}{12} = 3$, so $EF = 3 \cdot 16 = 48$.', '{"A":"Adds the difference between sides instead of using the ratio.","B":"Sets up the proportion with sides that do not correspond.","C":"Squares the scale factor; that applies to areas, not lengths."}'::jsonb),
  ('math.geo.lines', 'math.geo.lines.similar', 'hard', 1, 'mcq', null, 'Triangle $ABC$ is similar to triangle $DEF$, where $A$, $B$, and $C$ correspond to $D$, $E$, and $F$. If $AB = 12$, $BC = 6$, and $DE = 24$, what is $EF$?', '[{"id":"A","text":"$18$"},{"id":"B","text":"$48$"},{"id":"C","text":"$12$"},{"id":"D","text":"$24$"}]'::jsonb, '{"choice":"C"}'::jsonb, 'The scale factor is $\frac{DE}{AB} = \frac{24}{12} = 2$, so $EF = 2 \cdot 6 = 12$.', '{"A":"Adds the difference between sides instead of using the ratio.","B":"Sets up the proportion with sides that do not correspond.","D":"Squares the scale factor; that applies to areas, not lengths."}'::jsonb),
  ('math.geo.lines', 'math.geo.lines.similar', 'hard', 1, 'mcq', null, 'Triangle $ABC$ is similar to triangle $DEF$, where $A$, $B$, and $C$ correspond to $D$, $E$, and $F$. If $AB = 8$, $BC = 12$, and $DE = 24$, what is $EF$?', '[{"id":"A","text":"$36$"},{"id":"B","text":"$28$"},{"id":"C","text":"$16$"},{"id":"D","text":"$108$"}]'::jsonb, '{"choice":"A"}'::jsonb, 'The scale factor is $\frac{DE}{AB} = \frac{24}{8} = 3$, so $EF = 3 \cdot 12 = 36$.', '{"B":"Adds the difference between sides instead of using the ratio.","C":"Sets up the proportion with sides that do not correspond.","D":"Squares the scale factor; that applies to areas, not lengths."}'::jsonb),
